// ============ adaptive science-rover controller ============
var DEG = Math.PI / 180;
var WB = 0.6;
var RAY_A = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function isNum(v) { return typeof v === 'number' && v === v && v !== Infinity && v !== -Infinity; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function wrap180(a) {
  if (!isNum(a)) return 0;
  a = a % 360;
  if (a > 180) a -= 360;
  if (a < -180) a += 360;
  return a;
}
function dd(ax, ay, bx, by) { var dx = bx - ax, dy = by - ay; return Math.sqrt(dx * dx + dy * dy); }
function brgDeg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / DEG; }
function ema(o, n, a) { return o + (n - o) * a; }

function findSite(mem, id) {
  for (var i = 0; i < mem.sites.length; i++) if (mem.sites[i].id === id) return mem.sites[i];
  return null;
}
function dropFromPlan(mem, id) {
  var k = mem.plan.indexOf(id);
  if (k >= 0) mem.plan.splice(k, 1);
}
function cellIdx(mem, x, y) {
  var gx = Math.floor(x / mem.cell), gy = Math.floor(y / mem.cell);
  if (gx < 0 || gy < 0 || gx >= mem.gw || gy >= mem.gw) return -1;
  return gy * mem.gw + gx;
}

// ------------------------- init -------------------------
function initMem(obs, mem) {
  var m = obs.mission;
  mem.init = 1;
  mem.t0 = obs.t;
  mem.t = obs.t;
  mem.lastT = obs.t;
  mem.size = m.size;
  mem.seconds = m.seconds;
  mem.base = { x: m.base.x, y: m.base.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.sites = [];
  var hints = m.hints || [];
  for (var i = 0; i < hints.length; i++) {
    var hv = isNum(hints[i].estimate) ? hints[i].estimate : 5;
    mem.sites.push({
      id: i, x: hints[i].x, y: hints[i].y,
      est: hv, val: hv, known: 0, pReal: 0.86,
      status: 'todo', grabbed: 0
    });
  }
  mem.nextId = hints.length;
  mem.cell = 5;
  mem.gw = Math.ceil(m.size / mem.cell) + 2;
  var n = mem.gw * mem.gw;
  mem.grid = new Uint8Array(n);
  mem.aG = new Float32Array(n);
  mem.aP = new Int32Array(n);
  mem.aCl = new Uint8Array(n);

  mem.pos = { x: obs.x, y: obs.y };
  mem.gpsLast = { x: obs.x, y: obs.y };
  mem.gpsT = obs.t;
  mem.gpsAlive = 1;
  mem.heading = isNum(obs.heading) ? obs.heading : 0;
  mem.compassBias = 0;
  mem.biasInit = 0;
  mem.biasMiss = 0;
  mem.spdK = 1.9;
  mem.turnK = 95;
  mem.dz = 0.05;
  mem.dzCnt = 0;
  mem.speedAvg = 1.8;
  mem.sand = 1;
  mem.epm = 0.0022;
  mem.epDrill = 0.0025;
  mem.lastBattery = isNum(obs.battery) ? obs.battery : 1;
  mem.battery = mem.lastBattery;
  mem.lastLeft = 0;
  mem.lastRight = 0;
  mem.lastHeadingRaw = mem.heading;
  mem.lastCarried = isNum(obs.carried) ? obs.carried : 0;
  mem.carried = mem.lastCarried;
  mem.timeLeft = isNum(obs.timeLeft) ? obs.timeLeft : m.seconds;
  mem.vWheel = 0;
  mem.bumpedLast = 0;
  mem.recoverUntil = -1;
  mem.recoverDir = 1;
  mem.stuckT = 0;
  mem.state = 'PLAN';
  mem.plan = [];
  mem.planDirty = 1;
  mem.planT = -1e9;
  mem.wp = null;
  mem.wpT = -1e9;
  mem.wpGoal = { x: -1e9, y: -1e9 };
  mem.wpDirty = 1;
  mem.searchPts = null;
  mem.searchIdx = 0;
  mem.searchStart = 0;
  mem.searchId = -1;
  mem.searchSci = 0;
  mem.sampleId = -1;
  mem.sampleStart = 0;
  mem.drillOn = 0;
  mem.drillReady = 0;
  mem.holdGain = 0.32;
  mem.raySkip = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  mem.rayConst = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  mem.rayLast = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  mem.siteMatchId = -1;
  mem.siteD = -1;
  mem.sciMax = 0.0001;
  mem.sci = 0;
  mem.dockT0 = -1;
  mem.dockB0 = 0;
  mem.tripTimeEst = 0;
  mem.hist = { x: mem.pos.x, y: mem.pos.y, t: obs.t, w: 0, mt: 0 };
  mem.chist = { x: mem.pos.x, y: mem.pos.y, t: obs.t };
}

// --------------------- world update ---------------------
function updateBias(mem, hRaw, course) {
  var cand = wrap180(hRaw - course);
  if (!mem.biasInit) { mem.compassBias = cand; mem.biasInit = 1; return; }
  var d = wrap180(cand - mem.compassBias);
  var ad = Math.abs(d);
  if (ad < 14) { mem.compassBias = wrap180(mem.compassBias + d * 0.14); mem.biasMiss = 0; }
  else if (ad < 50) { mem.compassBias = wrap180(mem.compassBias + d * 0.035); mem.biasMiss = 0; }
  else {
    mem.biasMiss++;
    if (mem.biasMiss > 3) { mem.compassBias = cand; mem.biasMiss = 0; }
  }
}

function updateGrid(obs, mem, hR, vWheel) {
  if (!obs.rays) return;
  for (var i = 0; i < 9; i++) {
    var v = obs.rays[i];
    if (!isNum(v)) { mem.raySkip[i] = 1; continue; }
    if (v < 0.05) v = 0.05;
    if (Math.abs(v - mem.rayLast[i]) > 0.55) { mem.raySkip[i] = 0; mem.rayConst[i] = 0; }
    else if (Math.abs(vWheel) > 0.5 && v < 13) {
      mem.rayConst[i] += mem.dt;
      if (mem.rayConst[i] > 3.5) mem.raySkip[i] = 1;
    }
    mem.rayLast[i] = v;
    if (mem.raySkip[i]) continue;
    var d = v, blocked = 0;
    if (d > 14.6) { d = 15.2; } else { blocked = 1; }
    var a = hR + RAY_A[i] * DEG;
    var ca = Math.cos(a), sa = Math.sin(a);
    var steps = Math.max(1, Math.floor(d / 2.6));
    for (var s = 1; s <= steps; s++) {
      var tt = (s / steps) * d;
      var ci = cellIdx(mem, mem.pos.x + ca * tt, mem.pos.y + sa * tt);
      if (ci < 0) continue;
      if (blocked && s === steps) { if (mem.grid[ci] !== 2) mem.grid[ci] = 2; }
      else if (mem.grid[ci] === 0) mem.grid[ci] = 1;
    }
  }
}

function discoverSites(obs, mem) {
  mem.siteMatchId = -1;
  mem.siteD = -1;
  if (!obs.site || !isNum(obs.site.distance) || !isNum(obs.site.bearing)) return;
  var sd = clamp(obs.site.distance, 0, 12);
  var brg = wrap180(mem.heading + obs.site.bearing);
  var sx = mem.pos.x + sd * Math.cos(brg * DEG);
  var sy = mem.pos.y + sd * Math.sin(brg * DEG);
  mem.siteD = sd;
  var prefer = -1;
  if (mem.sampleId >= 0) prefer = mem.sampleId;
  else if (mem.searchId >= 0 && mem.state === 'SEARCH') prefer = mem.searchId;
  else if (mem.plan.length > 0) prefer = mem.plan[0];
  var best = -1;
  if (prefer >= 0) {
    var sp = findSite(mem, prefer);
    if (sp && sp.status === 'todo' && dd(sp.x, sp.y, sx, sy) < 34) {
      for (var q = 0; q < mem.sites.length; q++) if (mem.sites[q].id === prefer) { best = q; break; }
    }
  }
  if (best < 0) {
    var bestD = 30;
    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.status === 'sampled' || s.status === 'false' || s.status === 'skip') continue;
      var d = dd(s.x, s.y, sx, sy);
      if (d < bestD) { bestD = d; best = i; }
    }
  }
  if (best >= 0) {
    var s2 = mem.sites[best];
    s2.x = s2.x * 0.55 + sx * 0.45;
    s2.y = s2.y * 0.55 + sy * 0.45;
    s2.known = 1;
    s2.pReal = 1;
    if (isNum(obs.site.value)) { s2.val = obs.site.value; s2.est = obs.site.value; }
    mem.siteMatchId = s2.id;
  } else {
    var vv = isNum(obs.site.value) ? obs.site.value : 5;
    var ns = { id: mem.nextId++, x: sx, y: sy, est: vv, val: vv, known: 1, pReal: 1, status: 'todo', grabbed: 0 };
    mem.sites.push(ns);
    mem.siteMatchId = ns.id;
    mem.planDirty = 1;
  }
}

function updateWorld(obs, mem) {
  var dt = obs.t - mem.lastT;
  if (!(dt > 0.004)) dt = 0.004;
  if (dt > 0.4) dt = 0.4;
  mem.dt = dt;
  mem.t = obs.t;

  if (isNum(obs.carried)) mem.carried = obs.carried;
  if (isNum(obs.timeLeft)) mem.timeLeft = obs.timeLeft;
  else mem.timeLeft = Math.max(0, mem.seconds - (obs.t - mem.t0));
  if (isNum(obs.battery)) mem.battery = obs.battery;
  mem.sci = isNum(obs.science) ? obs.science : 0;
  if (mem.sci > mem.sciMax) mem.sciMax = mem.sci;

  var hRaw = isNum(obs.heading) ? obs.heading : mem.lastHeadingRaw;
  mem.heading = wrap180(hRaw - mem.compassBias);

  var wl = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  var wr = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  var vWheel = (wl + wr) / 2;
  mem.vWheel = vWheel;

  if (isNum(obs.x) && isNum(obs.y)) {
    var gm = dd(obs.x, obs.y, mem.gpsLast.x, mem.gpsLast.y);
    if (gm > 0.25) { mem.gpsLast.x = obs.x; mem.gpsLast.y = obs.y; mem.gpsT = obs.t; mem.gpsAlive = 1; }
    if (obs.t - mem.gpsT > 2.5) mem.gpsAlive = 0;
  }
  var hR = mem.heading * DEG;
  mem.pos.x += vWheel * Math.cos(hR) * dt;
  mem.pos.y += vWheel * Math.sin(hR) * dt;
  if (mem.gpsAlive && isNum(obs.x) && isNum(obs.y)) {
    mem.pos.x += (obs.x - mem.pos.x) * 0.5;
    mem.pos.y += (obs.y - mem.pos.y) * 0.5;
  }
  mem.pos.x = clamp(mem.pos.x, 1, mem.size - 1);
  mem.pos.y = clamp(mem.pos.y, 1, mem.size - 1);

  // long-window history: grip + compass course
  mem.hist.w += Math.abs(vWheel) * dt;
  if (Math.abs(vWheel) > 0.4) mem.hist.mt += dt;
  if (obs.t - mem.hist.t >= 2.5) {
    var dx = mem.pos.x - mem.hist.x, dy = mem.pos.y - mem.hist.y;
    var gw = Math.sqrt(dx * dx + dy * dy);
    var dw = mem.hist.w;
    if (dw > 1.5) {
      var ratio = gw / dw;
      mem.sand = ema(mem.sand, clamp(ratio, 0.15, 1.3), 0.25);
      if (gw > 4.5 && mem.gpsAlive && ratio > 0.68 && ratio < 1.35) {
        updateBias(mem, hRaw, Math.atan2(dy, dx) / DEG);
        mem.heading = wrap180(hRaw - mem.compassBias);
      }
    }
    if (mem.hist.mt > 1.0 && gw / Math.max(0.4, mem.hist.mt) > 0.4) {
      mem.speedAvg = ema(mem.speedAvg, gw / mem.hist.mt, 0.14);
    }
    mem.hist.x = mem.pos.x; mem.hist.y = mem.pos.y; mem.hist.t = obs.t;
    mem.hist.w = 0; mem.hist.mt = 0;
  }

  // motor response learning
  var diffCmd = mem.lastRight - mem.lastLeft;
  if (Math.abs(diffCmd) > 0.16) {
    var rate = wrap180(hRaw - mem.lastHeadingRaw) / dt;
    if (Math.abs(rate) < 420) {
      var k = rate / diffCmd;
      if (k > 3 && k < 420) mem.turnK = ema(mem.turnK, k, 0.07);
    }
  }
  var avgCmd = (mem.lastLeft + mem.lastRight) / 2;
  if (Math.abs(avgCmd) > 0.2) {
    var k2 = vWheel / avgCmd;
    if (k2 > 0.25 && k2 < 9) mem.spdK = ema(mem.spdK, k2, 0.07);
  }
  if (Math.abs(avgCmd) > 0.04 && Math.abs(vWheel) < 0.03) {
    mem.dzCnt++;
    if (mem.dzCnt > 8) mem.dz = Math.max(mem.dz, Math.abs(avgCmd) * 1.15);
  } else mem.dzCnt = 0;
  mem.dz = clamp(mem.dz - 0.00012, 0.02, 0.22);

  // energy model
  var dE = mem.lastBattery - mem.battery;
  if (dE > 0) {
    var moved = Math.abs(vWheel) * dt;
    if (mem.drillOn) mem.epDrill = ema(mem.epDrill, dE / dt, 0.05);
    else if (moved > 0.015) mem.epm = ema(mem.epm, dE / moved, 0.05);
  }
  mem.epm = clamp(mem.epm, 0.0002, 0.02);
  mem.epDrill = clamp(mem.epDrill, 0.0002, 0.03);

  updateGrid(obs, mem, hR, vWheel);
  discoverSites(obs, mem);
}

// ------------------------ A* ------------------------
function astar(mem, tx, ty) {
  var C = mem.cell, W = mem.gw, grid = mem.grid, n = W * W;
  var sx = clamp(Math.floor(mem.pos.x / C), 0, W - 1);
  var sy = clamp(Math.floor(mem.pos.y / C), 0, W - 1);
  var gx = clamp(Math.floor(tx / C), 0, W - 1);
  var gy = clamp(Math.floor(ty / C), 0, W - 1);
  var G = mem.aG, P = mem.aP, CL = mem.aCl;
  for (var i = 0; i < n; i++) { G[i] = 1e18; P[i] = -1; CL[i] = 0; }
  var start = sy * W + sx, goal = gy * W + gx;
  var hI = [], hF = [];
  G[start] = 0;
  hI.push(start); hF.push(0);
  var found = 0, iter = 0;
  while (hI.length > 0 && iter < 15000) {
    iter++;
    var cur = hI[0];
    var li = hI.pop(), lf = hF.pop();
    if (hI.length > 0) {
      hI[0] = li; hF[0] = lf;
      var k = 0;
      for (;;) {
        var l = 2 * k + 1, r = l + 1, s = k;
        if (l < hI.length && hF[l] < hF[s]) s = l;
        if (r < hI.length && hF[r] < hF[s]) s = r;
        if (s === k) break;
        var ti = hI[s], tf = hF[s];
        hI[s] = hI[k]; hF[s] = hF[k]; hI[k] = ti; hF[k] = tf;
        k = s;
      }
    }
    if (CL[cur]) continue;
    CL[cur] = 1;
    if (cur === goal) { found = 1; break; }
    var cx = cur % W, cy = (cur - cx) / W;
    for (var dy = -1; dy <= 1; dy++) {
      for (var dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        var nx = cx + dx, ny = cy + dy;
        if (nx < 0 || ny < 0 || nx >= W || ny >= W) continue;
        var ni = ny * W + nx;
        if (CL[ni]) continue;
        var step = (dx !== 0 && dy !== 0) ? 1.4142136 : 1;
        var st = grid[ni];
        var cost = st === 2 ? 13 : (st === 0 ? 2.2 : 1);
        if (ni === goal) cost = 0.6;
        var ng = G[cur] + step * cost;
        if (ng < G[ni]) {
          G[ni] = ng; P[ni] = cur;
          var hx = ni % W, hy = (ni - hx) / W;
          var adx = Math.abs(hx - gx), ady = Math.abs(hy - gy);
          var heur = (adx > ady ? adx : ady) + 0.4142136 * (adx < ady ? adx : ady);
          var f = ng + heur;
          hI.push(ni); hF.push(f);
          var kk = hI.length - 1;
          while (kk > 0) {
            var p = (kk - 1) >> 1;
            if (hF[p] <= hF[kk]) break;
            var t2i = hI[p], t2f = hF[p];
            hI[p] = hI[kk]; hF[p] = hF[kk]; hI[kk] = t2i; hF[kk] = t2f;
            kk = p;
          }
        }
      }
    }
  }
  var c = goal;
  if (!found) {
    var bestN = -1, bestF = 1e18;
    for (var q = 0; q < n; q++) {
      if (!CL[q]) continue;
      var qx = q % W, qy = (q - qx) / W;
      var adx2 = Math.abs(qx - gx), ady2 = Math.abs(qy - gy);
      var ff2 = G[q] + (adx2 > ady2 ? adx2 : ady2);
      if (ff2 < bestF) { bestF = ff2; bestN = q; }
    }
    if (bestN < 0) return null;
    c = bestN;
  }
  var path = [], guard = 0;
  while (c >= 0 && guard < 5000) {
    var ccx = c % W, ccy = (c - ccx) / W;
    path.push({ x: (ccx + 0.5) * C, y: (ccy + 0.5) * C });
    c = P[c];
    guard++;
  }
  path.reverse();
  path.push({ x: tx, y: ty });
  return path;
}

function lineClear(mem, x0, y0, x1, y1) {
  var d = dd(x0, y0, x1, y1);
  if (!(d > 0)) return true;
  if (d > 320) return false;
  var steps = Math.max(2, Math.ceil(d / 3));
  for (var s = 1; s < steps; s++) {
    var t = s / steps;
    var ci = cellIdx(mem, x0 + (x1 - x0) * t, y0 + (y1 - y0) * t);
    if (ci >= 0 && mem.grid[ci] === 2) return false;
  }
  return true;
}
function simplifyPath(mem, path) {
  if (!path || path.length < 3) return path;
  var out = [path[0]];
  var i = 0;
  while (i < path.length - 1) {
    var j = path.length - 1;
    while (j > i + 1) {
      if (lineClear(mem, path[i].x, path[i].y, path[j].x, path[j].y)) break;
      j--;
    }
    out.push(path[j]);
    i = j;
  }
  return out;
}

// -------------------- steering helpers --------------------
function nearEdge(mem) {
  var m = 22;
  return (mem.pos.x < m || mem.pos.y < m || mem.pos.x > mem.size - m || mem.pos.y > mem.size - m);
}
function edgeBias(mem) {
  var ix = 0, iy = 0, m = 32;
  if (mem.pos.x < m) ix += (m - mem.pos.x);
  if (mem.pos.x > mem.size - m) ix -= (mem.pos.x - (mem.size - m));
  if (mem.pos.y < m) iy += (m - mem.pos.y);
  if (mem.pos.y > mem.size - m) iy -= (mem.pos.y - (mem.size - m));
  if (ix === 0 && iy === 0) return 0;
  var want = Math.atan2(iy, ix) / DEG;
  var de = wrap180(want - mem.heading);
  var s = clamp(Math.sqrt(ix * ix + iy * iy) / m, 0, 1.3);
  return clamp(de * s * 1.0, -80, 80);
}
function avoidBias(obs, mem) {
  if (!obs.rays) return 0;
  var bias = 0, front = 15, leftOpen = 0, rightOpen = 0;
  for (var i = 0; i < 9; i++) {
    if (mem.raySkip[i]) continue;
    var v = obs.rays[i];
    if (!isNum(v) || v > 14.5) continue;
    var a = RAY_A[i];
    if (a === 0) { front = v; continue; }
    if (a > 0) { if (v > leftOpen) leftOpen = v; } else { if (v > rightOpen) rightOpen = v; }
    if (Math.abs(a) > 70) continue;
    var w = clamp(1 - v / 8.5, 0, 1);
    bias += (a > 0 ? -1 : 1) * w * w * 26;
  }
  if (front < 9.5) {
    var dir = (leftOpen >= rightOpen) ? 1 : -1;
    bias += dir * clamp(1 - front / 9.5, 0, 1) * 52;
  }
  return clamp(bias, -80, 80);
}
function toCmd(mem, vL, vR) {
  var k = mem.spdK;
  if (!(k > 0.2)) k = 1.5;
  var cl = clamp(vL / k, -1, 1);
  var cr = clamp(vR / k, -1, 1);
  var dz = mem.dz;
  if (Math.abs(cl) > 0.02 && Math.abs(cl) < dz) cl = (cl > 0 ? 1 : -1) * Math.min(dz, Math.abs(cl) * 2.0);
  if (Math.abs(cr) > 0.02 && Math.abs(cr) < dz) cr = (cr > 0 ? 1 : -1) * Math.min(dz, Math.abs(cr) * 2.0);
  return { left: cl, right: cr };
}

function driveTo(obs, mem, tx, ty, arriveR) {
  var px = mem.pos.x, py = mem.pos.y;
  tx = clamp(tx, 12, mem.size - 12);
  ty = clamp(ty, 12, mem.size - 12);
  var distT = dd(px, py, tx, ty);
  if (!mem.wp || mem.wpGoal.x !== tx || mem.wpGoal.y !== ty || (obs.t - mem.wpT) > 1.6 || mem.wpDirty) {
    var p = astar(mem, tx, ty);
    if (p && p.length > 2) p = simplifyPath(mem, p);
    mem.wp = p;
    mem.wpGoal = { x: tx, y: ty };
    mem.wpT = obs.t;
    mem.wpDirty = 0;
  }
  var aimX = tx, aimY = ty;
  if (mem.wp && mem.wp.length > 0) {
    var wp = mem.wp;
    while (wp.length > 1 && dd(px, py, wp[0].x, wp[0].y) < 4.2) wp.shift();
    for (var i = 0; i < wp.length; i++) {
      aimX = wp[i].x; aimY = wp[i].y;
      if (dd(px, py, aimX, aimY) > 8.5) break;
    }
  }
  var err = wrap180(brgDeg(px, py, aimX, aimY) - mem.heading);
  err = wrap180(err + avoidBias(obs, mem) + edgeBias(mem));

  var vMax = clamp(mem.spdK * 0.92, 0.9, 2.9);
  var sc = clamp(1 - Math.abs(err) / 85, 0.2, 1);
  var dF = 15, nSkip = 0;
  for (var r = 0; r < 9; r++) {
    if (mem.raySkip[r]) { nSkip++; continue; }
    var v = obs.rays ? obs.rays[r] : 15;
    if (!isNum(v) || v > 14.5) continue;
    if (Math.abs(RAY_A[r]) <= 30 && v < dF) dF = v;
  }
  if (dF < 10) sc *= clamp((dF - 1.8) / 8, 0.1, 1);
  if (distT < 16) sc *= clamp(distT / 16, 0.15, 1);
  if (arriveR && distT < arriveR * 2.2) sc *= 0.55;
  sc *= (0.5 + 0.5 * clamp(mem.sand, 0.3, 1.1));
  if (mem.battery < 0.1) sc *= 0.75;
  var vCmd = vMax * sc;

  var cap = 2.9;
  if (dF < 3.6) cap = 0.85;
  else if (dF < 6.5) cap = 1.55;
  if (nSkip >= 3) cap = Math.min(cap, 1.3);
  if (nearEdge(mem)) cap = Math.min(cap, 0.95);
  if (vCmd > cap) vCmd = cap;

  var turnRate = clamp(err * 1.55, -78, 78);
  var diff = turnRate / (mem.turnK > 5 ? mem.turnK : 95);
  var lim = Math.max(0.6, vMax);
  var vL = clamp(vCmd - diff / 2, -lim, lim);
  var vR = clamp(vCmd + diff / 2, -lim, lim);
  return toCmd(mem, vL, vR);
}

function holdCmd(obs, mem, ax, ay, useSite, vMaxH) {
  var px = mem.pos.x, py = mem.pos.y;
  var d = dd(px, py, ax, ay);
  var err = wrap180(brgDeg(px, py, ax, ay) - mem.heading);
  if (useSite && mem.siteD >= 0 && mem.siteMatchId >= 0) {
    d = mem.siteD;
    if (obs.site && isNum(obs.site.bearing)) err = obs.site.bearing;
  }
  var vNow = isNum(mem.vWheel) ? mem.vWheel : 0;
  var vDes = clamp((d - 0.5) * 0.8, 0, vMaxH);
  var pitch = isNum(obs.pitch) ? clamp(obs.pitch, -70, 70) : 0;
  var ff = clamp(Math.sin(pitch * DEG) * mem.holdGain, -0.9, 0.9);
  var u = ff + clamp((vDes - vNow) * 0.85, -0.8, 0.8);
  var turnRate = 0;
  if (d > 0.75) turnRate = clamp(err * 1.1, -28, 28);
  var diff = turnRate / (mem.turnK > 5 ? mem.turnK : 95);
  return toCmd(mem, u - diff / 2, u + diff / 2);
}

function makeSearchPts(mem, cx, cy) {
  var pts = [];
  var radii = [4, 9, 15, 22, 30];
  for (var r = 0; r < radii.length; r++) {
    var cnt = 4 + r * 2;
    for (var k = 0; k < cnt; k++) {
      var a = (k / cnt) * 2 * Math.PI + r * 0.9;
      pts.push({
        x: clamp(cx + radii[r] * Math.cos(a), 10, mem.size - 10),
        y: clamp(cy + radii[r] * Math.sin(a), 10, mem.size - 10)
      });
    }
  }
  return pts;
}

// ---------------------- planning ----------------------
function twoOpt(route, sx, sy, bx, by) {
  function tot(r) {
    var d = 0, px = sx, py = sy;
    for (var i = 0; i < r.length; i++) { d += dd(px, py, r[i].x, r[i].y); px = r[i].x; py = r[i].y; }
    return d + dd(px, py, bx, by);
  }
  var best = tot(route), improved = true, guard = 0;
  while (improved && guard < 25) {
    improved = false; guard++;
    for (var i = 0; i < route.length - 1; i++) {
      for (var j = i + 1; j < route.length; j++) {
        var mid = route.slice(i, j + 1).reverse();
        var r2 = route.slice(0, i).concat(mid, route.slice(j + 1));
        var t2 = tot(r2);
        if (t2 < best - 0.01) { best = t2; route = r2; improved = true; }
      }
    }
  }
  return route;
}

function planTrip(mem) {
  var sx = mem.pos.x, sy = mem.pos.y;
  var bx = mem.base.x, by = mem.base.y;
  mem.planT = mem.t;
  var slots = mem.cap - mem.carried;
  if (slots <= 0) { mem.plan = []; return; }
  var cands = [];
  for (var i = 0; i < mem.sites.length; i++) {
    if (mem.sites[i].status === 'todo') cands.push(mem.sites[i]);
  }
  var route = [];
  var speed = Math.max(1.15, mem.speedAvg);
  var siteTime = 17;
  var budget = Math.max(20, mem.timeLeft * 0.82 - 25);
  var used = dd(sx, sy, bx, by) / speed + 8;
  for (var it = 0; it < slots && cands.length > 0; it++) {
    var best = null, bestGain = -1, bestPos = -1, bestDt = 0;
    for (var ci = 0; ci < cands.length; ci++) {
      var c = cands[ci];
      var ev = c.known ? c.val : c.est * c.pReal;
      if (!(ev > 0)) continue;
      for (var p = 0; p <= route.length; p++) {
        var pxx = (p === 0 ? sx : route[p - 1].x), pyy = (p === 0 ? sy : route[p - 1].y);
        var nxx = (p === route.length ? bx : route[p].x), nyy = (p === route.length ? by : route[p].y);
        var delta = dd(pxx, pyy, c.x, c.y) + dd(c.x, c.y, nxx, nyy) - dd(pxx, pyy, nxx, nyy);
        var dtime = delta / speed + siteTime;
        if (dtime < 1) dtime = 1;
        var gain = ev / dtime;
        if (gain > bestGain) { bestGain = gain; best = c; bestPos = p; bestDt = dtime; }
      }
    }
    if (!best) break;
    if (bestGain < 0.03) break;
    route.splice(bestPos, 0, best);
    used += bestDt;
    if (used > budget) { route.splice(bestPos, 1); break; }
    var ix = cands.indexOf(best);
    if (ix >= 0) cands.splice(ix, 1);
  }
  route = twoOpt(route, sx, sy, bx, by);
  mem.plan = [];
  for (var q = 0; q < route.length; q++) mem.plan.push(route[q].id);
}

function routeLength(mem) {
  var d = 0, px = mem.pos.x, py = mem.pos.y;
  for (var i = 0; i < mem.plan.length; i++) {
    var s = findSite(mem, mem.plan[i]);
    if (!s) continue;
    d += dd(px, py, s.x, s.y); px = s.x; py = s.y;
  }
  return d + dd(px, py, mem.base.x, mem.base.y);
}

function needReturn(obs, mem) {
  var dB = dd(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  var speed = Math.max(1.15, mem.speedAvg);
  var tRet = dB / speed * 1.3 + 14;
  if (mem.timeLeft < tRet + 8) return true;
  var need = dB * mem.epm * 1.7 + 0.07;
  if (mem.battery < need) return true;
  if (mem.battery < 0.13) return true;
  return false;
}

function markBlockedAhead(mem) {
  var h = mem.heading * DEG;
  for (var k = 1; k <= 2; k++) {
    var ci = cellIdx(mem, mem.pos.x + Math.cos(h) * (2.4 + k * 2.3), mem.pos.y + Math.sin(h) * (2.4 + k * 2.3));
    if (ci >= 0) mem.grid[ci] = 2;
  }
}

function closeOut(cmd, obs, mem) {
  if (!isNum(cmd.left)) cmd.left = 0;
  if (!isNum(cmd.right)) cmd.right = 0;
  cmd.left = clamp(cmd.left, -1, 1);
  cmd.right = clamp(cmd.right, -1, 1);
  cmd.drill = cmd.drill ? true : false;
  mem.lastT = obs.t;
  mem.lastHeadingRaw = isNum(obs.heading) ? obs.heading : mem.lastHeadingRaw;
  mem.lastLeft = cmd.left;
  mem.lastRight = cmd.right;
  mem.lastBattery = isNum(obs.battery) ? obs.battery : mem.lastBattery;
  mem.bumpedLast = obs.bumped ? 1 : 0;
  return cmd;
}

// ------------------------ main ------------------------
function act(obs, mem) {
  if (!mem.init) initMem(obs, mem);
  updateWorld(obs, mem);
  var cmd = { left: 0, right: 0, drill: false };
  var t = obs.t;

  // ---- sample delivered to our cargo bay ----
  if (mem.carried > mem.lastCarried) {
    if (mem.sampleId >= 0) {
      var ss = findSite(mem, mem.sampleId);
      if (ss) ss.status = 'sampled';
    }
    mem.sampleId = -1;
    mem.drillOn = 0;
    mem.drillReady = 0;
    if (mem.state === 'SAMPLE') mem.state = 'PLAN';
    mem.planDirty = 1;
    mem.wpDirty = 1;
  }
  mem.lastCarried = mem.carried;

  // ---- bump / stuck recovery ----
  if (obs.bumped && !mem.bumpedLast) {
    mem.recoverUntil = t + 1.25;
    mem.recoverDir = -mem.recoverDir;
    mem.wpDirty = 1;
    markBlockedAhead(mem);
  }
  if (Math.abs(mem.lastLeft) + Math.abs(mem.lastRight) > 0.55 &&
      Math.abs(mem.vWheel) < 0.1 && mem.state !== 'SAMPLE' && mem.state !== 'DOCK' && t > 2) {
    mem.stuckT += mem.dt;
    if (mem.stuckT > 2.0) {
      mem.stuckT = 0;
      mem.recoverUntil = t + 1.35;
      mem.recoverDir = -mem.recoverDir;
      mem.wpDirty = 1;
      markBlockedAhead(mem);
    }
  } else {
    mem.stuckT = Math.max(0, mem.stuckT - mem.dt * 0.7);
  }
  if (t < mem.recoverUntil) {
    var ph = t - (mem.recoverUntil - 1.35);
    if (ph < 0.75) { cmd.left = -0.5; cmd.right = -0.5; }
    else { cmd.left = -0.42 * mem.recoverDir; cmd.right = 0.42 * mem.recoverDir; }
    return closeOut(cmd, obs, mem);
  }

  // ---- refine base position from beacon ----
  if (obs.beacon && isNum(obs.beacon.distance) && isNum(obs.beacon.bearing)) {
    var bb = wrap180(mem.heading + obs.beacon.bearing);
    mem.base.x = clamp(mem.pos.x + obs.beacon.distance * Math.cos(bb * DEG), 8, mem.size - 8);
    mem.base.y = clamp(mem.pos.y + obs.beacon.distance * Math.sin(bb * DEG), 8, mem.size - 8);
  }

  // ---- decide the state ----
  if (mem.state === 'PLAN') {
    if (mem.carried >= mem.cap || needReturn(obs, mem)) {
      mem.state = 'RETURN'; mem.wpDirty = 1;
    } else {
      if (mem.planDirty || mem.plan.length === 0) { planTrip(mem); mem.planDirty = 0; }
      while (mem.plan.length > 0) {
        var s0 = findSite(mem, mem.plan[0]);
        if (!s0 || s0.status !== 'todo') mem.plan.shift();
        else break;
      }
      if (mem.plan.length === 0) {
        if (mem.carried > 0) mem.state = 'RETURN';
        else if (dd(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) > 4) mem.state = 'RETURN';
        else mem.state = 'DOCK';
      } else {
        mem.state = 'GOTO';
      }
    }
  }

  // ---- act ----
  if (mem.state === 'SAMPLE') {
    var sS = findSite(mem, mem.sampleId);
    if (!sS || sS.status !== 'todo') {
      mem.state = 'PLAN'; mem.sampleId = -1; mem.drillOn = 0;
    } else {
      var useS = (mem.siteMatchId === mem.sampleId && mem.siteD >= 0);
      var hS = holdCmd(obs, mem, sS.x, sS.y, useS, 0.35);
      cmd.left = hS.left; cmd.right = hS.right;
      var dSite = useS ? mem.siteD : dd(mem.pos.x, mem.pos.y, sS.x, sS.y);
      var spd = Math.abs(mem.vWheel);
      var okDrill = (dSite < 1.35 && spd < 0.13);
      if (okDrill) mem.drillReady++;
      else mem.drillReady = 0;
      if (mem.drillOn) {
        cmd.drill = true;
        if (dSite > 1.75 || spd > 0.22) { mem.drillOn = 0; cmd.drill = false; }
      } else if (mem.drillReady >= 2) {
        mem.drillOn = 1;
        cmd.drill = true;
      }
      if (Math.abs(isNum(obs.pitch) ? obs.pitch : 0) > 2 && Math.abs(mem.vWheel) > 0.11) {
        mem.holdGain = clamp(mem.holdGain * 1.015, 0.12, 1.1);
      }
      if (t - mem.sampleStart > 32) {
        sS.status = 'skip';
        dropFromPlan(mem, sS.id);
        mem.sampleId = -1; mem.drillOn = 0; cmd.drill = false;
        mem.planDirty = 1; mem.state = 'PLAN';
      }
    }
  } else if (mem.state === 'SEARCH') {
    var sQ = findSite(mem, mem.searchId);
    if (!sQ || sQ.status !== 'todo') {
      mem.state = 'PLAN'; mem.searchPts = null;
    } else if (mem.siteMatchId === mem.searchId && mem.siteD >= 0) {
      sQ.known = 1;
      mem.searchPts = null;
      mem.state = 'GOTO';
    } else {
      if (!mem.searchPts) {
        mem.searchPts = makeSearchPts(mem, sQ.x, sQ.y);
        mem.searchIdx = 0;
        mem.searchStart = t;
      }
      var pts = mem.searchPts;
      while (mem.searchIdx < pts.length &&
             dd(mem.pos.x, mem.pos.y, pts[mem.searchIdx].x, pts[mem.searchIdx].y) < 3.5) mem.searchIdx++;
      var budget = mem.searchSci > 0 ? (10 + 26 * mem.searchSci) : 9;
      if (mem.searchIdx >= pts.length || t - mem.searchStart > budget) {
        sQ.status = 'false';
        dropFromPlan(mem, sQ.id);
        mem.searchPts = null;
        mem.searchId = -1;
        mem.planDirty = 1;
        mem.state = 'PLAN';
      } else {
        var tp = pts[mem.searchIdx];
        var cQ = driveTo(obs, mem, tp.x, tp.y, 3.5);
        cmd.left = cQ.left; cmd.right = cQ.right;
      }
    }
  } else if (mem.state === 'GOTO') {
    if (mem.plan.length === 0) {
      mem.state = 'PLAN';
    } else {
      var sG = findSite(mem, mem.plan[0]);
      if (!sG || sG.status !== 'todo') {
        if (sG) dropFromPlan(mem, sG.id);
        mem.state = 'PLAN';
      } else {
        if (mem.siteMatchId >= 0 && mem.siteMatchId !== sG.id && mem.carried < mem.cap) {
          var so = findSite(mem, mem.siteMatchId);
          if (so && so.status === 'todo' && !so.grabbed) {
            so.grabbed = 1;
            if (so.val >= sG.val * 0.5 || dd(mem.pos.x, mem.pos.y, sG.x, sG.y) > 26) {
              mem.plan.unshift(so.id);
              mem.planDirty = 1;
              sG = so;
            }
          }
        }
        var useG = (mem.siteMatchId === sG.id && mem.siteD >= 0);
        var dG = useG ? mem.siteD : dd(mem.pos.x, mem.pos.y, sG.x, sG.y);
        if (sG.known && dG < 2.4) {
          mem.state = 'SAMPLE'; mem.sampleId = sG.id; mem.sampleStart = t;
          mem.drillOn = 0; mem.drillReady = 0;
          cmd.left = 0; cmd.right = 0;
        } else if (!sG.known && dG < 7.0) {
          mem.state = 'SEARCH'; mem.searchId = sG.id; mem.searchPts = null;
          mem.searchSci = mem.sci > 0 ? clamp(mem.sci / Math.max(mem.sciMax, 1e-9), 0.15, 1) : 0;
          cmd.left = 0; cmd.right = 0;
        } else {
          if (mem.planDirty && (obs.t - mem.planT) > 6 && dG > 35) {
            mem.state = 'PLAN';
          } else {
            var cG = driveTo(obs, mem, sG.x, sG.y, sG.known ? 1.6 : 6);
            cmd.left = cG.left; cmd.right = cG.right;
          }
        }
      }
    }
  } else if (mem.state === 'RETURN') {
    var dR = dd(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (obs.docked || dR < 3.3) {
      var hR2 = holdCmd(obs, mem, mem.base.x, mem.base.y, 0, 0.8);
      cmd.left = hR2.left; cmd.right = hR2.right;
      if (Math.abs(mem.vWheel) < 0.22 || obs.docked) {
        mem.state = 'DOCK';
        mem.dockT0 = t;
        mem.dockB0 = mem.battery;
        cmd.left = 0; cmd.right = 0;
      }
    } else {
      var cR = driveTo(obs, mem, mem.base.x, mem.base.y, 3);
      cmd.left = cR.left; cmd.right = cR.right;
    }
  } else if (mem.state === 'DOCK') {
    var dD = dd(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (dD > 5.5) {
      mem.state = 'RETURN';
    } else {
      var hD = holdCmd(obs, mem, mem.base.x, mem.base.y, 0, 0.55);
      cmd.left = hD.left; cmd.right = hD.right;
      if (mem.dockT0 < 0) { mem.dockT0 = t; mem.dockB0 = mem.battery; }
      var dtD = Math.max(0.5, t - mem.dockT0);
      var rate = (mem.battery - mem.dockB0) / dtD;
      if (mem.carried === 0 && (mem.planDirty || mem.plan.length === 0 || t - mem.planT > 12)) {
        planTrip(mem);
        mem.planDirty = 0;
        while (mem.plan.length > 0) {
          var sP = findSite(mem, mem.plan[0]);
          if (!sP || sP.status !== 'todo') mem.plan.shift();
          else break;
        }
        if (mem.plan.length > 0) {
          var len = routeLength(mem);
          mem.tripTimeEst = len / Math.max(1.2, mem.speedAvg) + 18 * mem.plan.length + 30;
        } else mem.tripTimeEst = 0;
      }
      var ready = 0;
      if (mem.carried === 0 && mem.plan.length > 0) {
        if (mem.battery >= 0.92) ready = 1;
        else if (t - mem.dockT0 > 55) ready = 1;
        else if (mem.battery > 0.72 && rate < 0.004 && t - mem.dockT0 > 12) ready = 1;
        else if (mem.battery > mem.dockB0 + 0.25 && t - mem.dockT0 > 15) ready = 1;
        if (mem.timeLeft < mem.tripTimeEst + 25) ready = 0;
      }
      if (ready) {
        mem.state = 'GOTO';
        mem.dockT0 = -1;
        mem.wpDirty = 1;
      }
    }
  } else {
    mem.state = 'PLAN';
  }

  return closeOut(cmd, obs, mem);
}

var DR = Math.PI / 180;
function w(a){a=a%360;return a>180?a-360:(a<-180?a+360:a);}
function ds(ax,ay,bx,by){var x=bx-ax,y=by-ay;return Math.sqrt(x*x+y*y);}
function cp(v,a,b){return v<a?a:(v>b?b:v);}
function gi(m,x,y){var a=Math.floor(x/m.cs),b=Math.floor(y/m.cs);return(a<0||b<0||a>=m.gw||b>=m.gw)?-1:b*m.gw+a;}
function gs(m,id){for(var i=0;i<m.sites.length;i++)if(m.sites[i].id===id)return m.sites[i];return null;}

function astar(m,tx,ty){
  var C=m.cs,W=m.gw,G=m.gd,P=m.gp,CL=m.gc,n=W*W;
  var sx=cp(Math.floor(m.px/C),0,W-1),sy=cp(Math.floor(m.py/C),0,W-1);
  var gx=cp(Math.floor(tx/C),0,W-1),gy=cp(Math.floor(ty/C),0,W-1);
  var start=sy*W+sx,goal=gy*W+gx;
  for(var i=0;i<n;i++){G[i]=1e18;P[i]=-1;CL[i]=0;}
  G[start]=0;
  var hI=[start],hF=[0],iter=0;
  while(hI.length>0&&iter<10000){
    iter++;
    var cur=hI[0],li=hI.pop(),lf=hF.pop();
    if(hI.length>0){hI[0]=li;hF[0]=lf;var k=0;
      for(;;){var l=2*k+1,r=l+1,s=k;
        if(l<hI.length&&hF[l]<hF[s])s=l;
        if(r<hI.length&&hF[r]<hF[s])s=r;
        if(s===k)break;
        var ti=hI[s],tf=hF[s];hI[s]=hI[k];hF[s]=hF[k];hI[k]=ti;hF[k]=tf;k=s;}}
    if(CL[cur])continue;
    CL[cur]=1;
    if(cur===goal)break;
    var cx=cur%W,cy=(cur-cx)/W;
    for(var dy=-1;dy<=1;dy++)for(var dx=-1;dx<=1;dx++){
      if(!dx&&!dy)continue;
      var nx=cx+dx,ny=cy+dy;
      if(nx<0||ny<0||nx>=W||ny>=W)continue;
      var ni=ny*W+nx;
      if(CL[ni])continue;
      var st=m.grid[ni];
      if(st===3&&ni!==goal)continue;
      var cost=st===0?2.5:1;
      if(dx&&dy)cost*=1.414;
      if(ni===goal)cost*=0.3;
      var ng=G[cur]+cost;
      if(ng<G[ni]){
        G[ni]=ng;P[ni]=cur;
        var hx=ni%W,hy=(ni-hx)/W;
        var ax=Math.abs(hx-gx),ay=Math.abs(hy-gy);
        hI.push(ni);hF.push(ng+Math.max(ax,ay)+0.414*Math.min(ax,ay));
        var kk=hI.length-1;
        while(kk>0){var pp=(kk-1)>>1;if(hF[pp]<=hF[kk])break;
          var t2i=hI[pp],t2f=hF[pp];hI[pp]=hI[kk];hF[pp]=hF[kk];hI[kk]=t2i;hF[kk]=t2f;kk=pp;}
      }
    }
  }
  var path=[],c=CL[goal]?goal:-1;
  if(c<0){var bd=1e18;for(var q=0;q<n;q++){if(!CL[q])continue;
    var qx=q%W,qy=(q-qx)/W,d=Math.abs(qx-gx)+Math.abs(qy-gy);
    if(d<bd){bd=d;c=q;}}}
  if(c<0)return[];
  var g=0;
  while(c>=0&&g<5000){var ccx=c%W,ccy=(c-ccx)/W;
    path.push({x:(ccx+0.5)*C,y:(ccy+0.5)*C});c=P[c];g++;}
  path.reverse();path.push({x:tx,y:ty});
  return path;
}

function simpPath(m,path){
  if(!path||path.length<3)return path||[];
  var out=[path[0]],i=0,steps=0;
  while(i<path.length-1&&steps<300){
    var j=path.length-1;
    while(j>i+1&&steps<300){if(lineFree(m,path[i],path[j]))break;j--;steps++;}
    out.push(path[j]);i=j;
  }
  return out;
}

function lineFree(m,p1,p2){
  var d=ds(p1.x,p1.y,p2.x,p2.y);
  if(d<1)return true;
  if(d>200)return false;
  var steps=Math.ceil(d/3);
  for(var s=1;s<steps;s++){
    var t=s/steps;
    var ci=gi(m,p1.x+(p2.x-p1.x)*t,p1.y+(p2.y-p1.y)*t);
    if(ci>=0&&m.grid[ci]===3)return false;
  }
  return true;
}

function navigate(obs,m,tx,ty){
  if(!m.path||m.path.length===0||!m.ptg||ds(m.ptg.x,m.ptg.y,tx,ty)>5||obs.t-m.pt>5){
    m.path=simpPath(m,astar(m,tx,ty));
    m.ptg={x:tx,y:ty};m.pt=obs.t;m.pi=0;
  }
  var aimX=tx,aimY=ty;
  if(m.path.length>0){
    while(m.pi<m.path.length-1&&ds(obs.x,obs.y,m.path[m.pi].x,m.path[m.pi].y)<5)m.pi++;
    aimX=m.path[m.pi].x;aimY=m.path[m.pi].y;
    for(var i=m.pi;i<m.path.length;i++){
      if(ds(obs.x,obs.y,m.path[i].x,m.path[i].y)>10)break;
      aimX=m.path[i].x;aimY=m.path[i].y;
    }
  }
  var dx=aimX-obs.x,dy=aimY-obs.y;
  var distT=Math.sqrt(dx*dx+dy*dy);
  var des=Math.atan2(dy,dx)/DR;
  var hErr=w(des-(obs.heading||0));
  var avoid=0,mF=15,lO=15,rO=15;
  if(obs.rays){
    var RA=[-80,-60,-40,-20,0,20,40,60,80];
    for(var ri=0;ri<9;ri++){
      var v=obs.rays[ri];
      if(typeof v!=='number'||v!==v||v>14.5)continue;
      if(Math.abs(RA[ri])<=30&&v<mF)mF=v;
      if(RA[ri]>20&&v<lO)lO=v;
      if(RA[ri]<-20&&v<rO)rO=v;
      if(Math.abs(RA[ri])>70)continue;
      var w2=cp(1-v/8,0,1);
      avoid+=(RA[ri]>0?-1:1)*w2*w2*22;
    }
    if(mF<7)avoid+=(lO>rO?1:-1)*cp(1-mF/7,0,1)*35;
  }
  var steer=hErr+avoid;
  var speed=1.0;
  if(mF<2)speed*=0.05;
  else if(mF<3)speed*=0.15;
  else if(mF<5)speed*=0.35;
  else if(mF<8)speed*=0.65;
  if(distT<15)speed*=cp(distT/15,0.1,1);
  if(Math.abs(steer)>40)speed*=0.35;
  else if(Math.abs(steer)>20)speed*=0.65;
  var steerC=cp(steer*0.016,-0.55,0.55);
  var fwd=speed*0.65;
  var maxC=1.0;
  if(mF<2)maxC=0.15;
  else if(mF<3)maxC=0.3;
  else if(mF<5)maxC=0.5;
  return{left:cp(fwd-steerC,-maxC,maxC),right:cp(fwd+steerC,-maxC,maxC),drill:false};
}

function act(obs,mem){
  if(!mem.init){
    var m=obs.mission;
    mem.init=1;mem.size=m.size;mem.seconds=m.seconds;
    mem.bx=m.base.x;mem.by=m.base.y;
    mem.cap=m.capacity||5;
    mem.sites=[];
    var hints=m.hints||[];
    for(var h=0;h<hints.length;h++)
      mem.sites.push({id:h,x:hints[h].x,y:hints[h].y,val:hints[h].estimate||5,sampled:false});
    mem.nid=hints.length;
    mem.cs=4;mem.gw=Math.ceil(m.size/mem.cs)+1;
    var n=mem.gw*mem.gw;
    mem.grid=new Uint8Array(n);mem.gd=new Float32Array(n);
    mem.gp=new Int32Array(n);mem.gc=new Uint8Array(n);
    mem.state='PLAN';mem.path=[];mem.pi=0;mem.ptg=null;mem.pt=0;
    mem.tgtId=-1;mem.drillT=0;mem.stuckT=0;
    mem.recP=-1;mem.recT=0;
    mem.dockT=-1;mem.dockB=0;
    mem.searchT=-1;mem.searchCx=0;mem.searchCy=0;
    mem.px=obs.x;mem.py=obs.y;
    mem.vEst=1.5;mem.epm=0.0005;
    mem.lastT=obs.t;mem.lastX=obs.x;mem.lastY=obs.y;
    mem.lastB=obs.battery||1;mem.lastCarried=obs.carried||0;
    mem.cmdL=0;mem.cmdR=0;mem.lastBump=0;
    mem.approachT=-1;mem.detectedSiteId=-1;
    mem.recCount=0;
  }

  var dt=Math.max(0.01,Math.min(0.5,obs.t-mem.lastT));
  mem.lastT=obs.t;mem.px=obs.x;mem.py=obs.y;
  var moved=ds(obs.x,obs.y,mem.lastX,mem.lastY);
  mem.vEst=mem.vEst*0.85+(moved/dt)*0.15;
  mem.lastX=obs.x;mem.lastY=obs.y;
  var dB=mem.lastB-(obs.battery||mem.lastB);
  if(moved>0.02&&!(obs.drilling>0)){
    mem.epm=mem.epm*0.95+(dB/moved)*0.05;
    mem.epm=cp(mem.epm,0.0001,0.01);
  }
  mem.lastB=obs.battery||mem.lastB;

  if(obs.rays&&obs.rays.length===9){
    var hdg=(obs.heading||0)*DR;
    var RA=[-80,-60,-40,-20,0,20,40,60,80];
    for(var i=0;i<9;i++){
      var v=obs.rays[i];
      if(typeof v!=='number'||v!==v)continue;
      var ang=hdg+RA[i]*DR,ca=Math.cos(ang),sa=Math.sin(ang);
      var hitD=(v>14.5)?15:Math.max(1,v);
      for(var d=3;d<hitD-1.5;d+=3){
        var ci=gi(mem,obs.x+ca*d,obs.y+sa*d);
        if(ci>=0&&mem.grid[ci]<3)mem.grid[ci]=1;
      }
      if(v<14.5&&v>1){var ci2=gi(mem,obs.x+ca*v,obs.y+sa*v);if(ci2>=0)mem.grid[ci2]=3;}
    }
    var ci3=gi(mem,obs.x,obs.y);if(ci3>=0)mem.grid[ci3]=1;
  }

  mem.detectedSiteId=-1;
  if(obs.site&&obs.site.distance<8){
    var sd=obs.site.distance;
    var sb=w((obs.heading||0)+obs.site.bearing);
    var sx=obs.x+sd*Math.cos(sb*DR),sy=obs.y+sd*Math.sin(sb*DR);
    var bm=-1,bd=35;
    for(var si=0;si<mem.sites.length;si++){
      if(mem.sites[si].sampled)continue;
      var dd=ds(mem.sites[si].x,mem.sites[si].y,sx,sy);
      if(dd<bd){bd=dd;bm=si;}
    }
    if(bm>=0){
      mem.sites[bm].x=mem.sites[bm].x*0.5+sx*0.5;
      mem.sites[bm].y=mem.sites[bm].y*0.5+sy*0.5;
      if(obs.site.value)mem.sites[bm].val=obs.site.value;
      mem.detectedSiteId=mem.sites[bm].id;
    }else{
      var ns={id:mem.nid++,x:sx,y:sy,val:obs.site.value||5,sampled:false};
      mem.sites.push(ns);mem.detectedSiteId=ns.id;
    }
  }

  if((obs.carried||0)>mem.lastCarried){
    var ts=gs(mem,mem.tgtId);
    if(ts)ts.sampled=true;
    mem.tgtId=-1;mem.drillT=0;mem.state='PLAN';
  }
  mem.lastCarried=obs.carried||0;

  if(mem.recP>=0){
    mem.recT+=dt;
    var rc={left:0,right:0,drill:false};
    if(mem.recP===0){if(mem.recT>0.3){mem.recP=1;mem.recT=0;}}
    else if(mem.recP===1){
      rc.left=-0.5;rc.right=-0.5;
      if(mem.recT>2.5){mem.recP=2;mem.recT=0;}
    }else if(mem.recP===2){
      var bA=0,bV=0;
      if(obs.rays)for(var ri=0;ri<9;ri++)
        if(obs.rays[ri]>bV){bV=obs.rays[ri];bA=[-80,-60,-40,-20,0,20,40,60,80][ri];}
      var td=bA>=0?1:-1;
      rc.left=-0.35*td;rc.right=0.35*td;
      if(mem.recT>1.8){
        mem.recP=-1;mem.recT=0;mem.stuckT=0;
        var h2=(obs.heading||0)*DR;
        for(var dd2=2;dd2<12;dd2+=3){
          var ci=gi(mem,obs.x+Math.cos(h2)*dd2,obs.y+Math.sin(h2)*dd2);
          if(ci>=0)mem.grid[ci]=3;
        }
        mem.path=[];mem.state='PLAN';mem.recCount++;
      }
    }
    mem.cmdL=rc.left;mem.cmdR=rc.right;
    return rc;
  }

  var wM=Math.abs(mem.cmdL)+Math.abs(mem.cmdR)>0.25;
  var whM=Math.abs(obs.wheelLeft||0)+Math.abs(obs.wheelRight||0)>0.3;
  if(wM&&moved<0.03){
    var threshold=whM?3.0:1.5;
    mem.stuckT+=dt;
    if(mem.stuckT>threshold){
      mem.recP=0;mem.recT=0;mem.stuckT=0;
      return{left:0,right:0,drill:false};
    }
  }else{mem.stuckT=Math.max(0,mem.stuckT-dt*0.5);}

  if(obs.bumped&&!mem.lastBump){
    mem.recP=1;mem.recT=0;mem.stuckT=0;mem.path=[];
    mem.lastBump=1;
    var rb={left:-0.45,right:-0.45,drill:false};
    mem.cmdL=rb.left;mem.cmdR=rb.right;
    return rb;
  }
  mem.lastBump=obs.bumped?1:0;

  var needRet=false;
  var dBase=ds(obs.x,obs.y,mem.bx,mem.by);
  var carryF=1+(obs.carried||0)*0.08;
  if((obs.timeLeft||0)<dBase/1.2*1.5+15)needRet=true;
  if(obs.battery<dBase*mem.epm*carryF*2.0+0.06)needRet=true;
  if(obs.battery<0.12)needRet=true;

  if(needRet&&mem.state!=='DOCK'&&mem.state!=='RECOVER'){
    var nearDrill=(mem.state==='SAMPLE'&&obs.drilling>4);
    if(!nearDrill){
      mem.state='NAV';mem.tgtId=-1;mem.path=[];
    }
  }

  var cmd={left:0,right:0,drill:false};

  if(mem.state==='PLAN'){
    if(needRet||(obs.carried||0)>=mem.cap){
      mem.state='NAV';mem.tgtId=-1;mem.path=[];
    }else{
      var bs=null,bsc=-1;
      for(var si2=0;si2<mem.sites.length;si2++){
        var s=mem.sites[si2];
        if(s.sampled)continue;
        var dS=ds(obs.x,obs.y,s.x,s.y);
        var dBk=ds(s.x,s.y,mem.bx,mem.by);
        var tN=(dS+dBk)/1.5+12;
        if((obs.timeLeft||0)<tN+15)continue;
        var eNeed=(dS+dBk)*mem.epm*carryF*1.8+0.08;
        if(obs.battery<eNeed)continue;
        var sc=s.val/Math.max(1,tN);
        if(sc>bsc){bsc=sc;bs=s;}
      }
      if(bs){mem.tgtId=bs.id;mem.state='NAV';mem.path=[];}
      else{mem.state='NAV';mem.tgtId=-1;mem.path=[];}
    }
  }

  if(mem.state==='NAV'){
    if(mem.tgtId>=0){
      var ts=gs(mem,mem.tgtId);
      if(!ts||ts.sampled){mem.state='PLAN';mem.path=[];}
      else{
        if(obs.site&&obs.site.distance<8){
          var sd2=obs.site.distance;
          var sb2=w((obs.heading||0)+obs.site.bearing);
          ts.x=ts.x*0.5+(obs.x+sd2*Math.cos(sb2*DR))*0.5;
          ts.y=ts.y*0.5+(obs.y+sd2*Math.sin(sb2*DR))*0.5;
        }
        var dT=ds(obs.x,obs.y,ts.x,ts.y);
        if(obs.site&&obs.site.distance<3){
          mem.state='APPROACH';mem.approachT=obs.t;
        }else if(dT<2.5&&!obs.site){
          mem.searchT=obs.t;mem.searchCx=ts.x;mem.searchCy=ts.y;
          mem.state='SEARCH';
        }
        if(mem.state==='NAV')cmd=navigate(obs,mem,ts.x,ts.y);
      }
    }else{
      if(obs.beacon&&obs.beacon.distance<25){
        var bb=w((obs.heading||0)+obs.beacon.bearing);
        mem.bx=obs.x+obs.beacon.distance*Math.cos(bb*DR);
        mem.by=obs.y+obs.beacon.distance*Math.sin(bb*DR);
      }
      var dT2=ds(obs.x,obs.y,mem.bx,mem.by);
      if(dT2<3.5){mem.state='DOCK';mem.dockT=-1;}
      else cmd=navigate(obs,mem,mem.bx,mem.by);
    }
  }

  if(mem.state==='SEARCH'){
    if(obs.site&&obs.site.distance<8){
      if(mem.detectedSiteId>=0)mem.tgtId=mem.detectedSiteId;
      mem.state='APPROACH';mem.approachT=obs.t;
    }else if(obs.t-mem.searchT>15){
      var ts=gs(mem,mem.tgtId);
      if(ts)ts.sampled=true;
      mem.state='PLAN';
    }else{
      var st=obs.t-mem.searchT;
      var ang=st*0.35;
      var radius=Math.min(15,st*1.0);
      var sX=cp(mem.searchCx+radius*Math.cos(ang),12,mem.size-12);
      var sY=cp(mem.searchCy+radius*Math.sin(ang),12,mem.size-12);
      cmd=navigate(obs,mem,sX,sY);
    }
  }

  if(mem.state==='APPROACH'){
    var ts=gs(mem,mem.tgtId);
    if(!ts||ts.sampled){mem.state='PLAN';}
    else if(!obs.site||obs.site.distance>5){
      if(obs.t-mem.approachT>8)mem.state='NAV';
    }else{
      var dS=obs.site.distance,bS=obs.site.bearing;
      var vNow2=Math.abs((obs.wheelLeft||0)+(obs.wheelRight||0))/2;
      if(Math.abs(bS)>60){
        var td=bS>0?1:-1;
        var tSpd=0.3;
        if(obs.rays){var mf=15;for(var ri=0;ri<9;ri++)if(obs.rays[ri]<mf)mf=obs.rays[ri];if(mf<3)tSpd=0.15;}
        cmd.left=-tSpd*td;cmd.right=tSpd*td;
      }else if(dS<1.35&&vNow2<0.12){
        mem.state='SAMPLE';mem.drillT=0;
        cmd.left=0;cmd.right=0;
      }else{
        var fwd=cp(dS*0.12,0.03,0.25);
        var steer=cp(bS*0.012,-0.15,0.15);
        cmd.left=cp(fwd-steer,-0.3,0.3);
        cmd.right=cp(fwd+steer,-0.3,0.3);
      }
    }
  }

  if(mem.state==='SAMPLE'){
    if(!obs.site||obs.site.distance>2.5){
      mem.state='PLAN';mem.drillT=0;
    }else{
      var dS2=obs.site.distance,bS2=obs.site.bearing;
      var pitch=obs.pitch||0;
      var hold=cp(pitch*0.025,-0.35,0.35);
      var vNow3=((obs.wheelLeft||0)+(obs.wheelRight||0))/2;
      var fwdT=dS2>1.0?cp((dS2-0.5)*0.15,0,0.2):0;
      var vErr=fwdT-vNow3;
      var fwd2=hold+cp(vErr*0.5,-0.3,0.3);
      var steer2=cp(bS2*0.01,-0.12,0.12);
      cmd.left=cp(fwd2-steer2,-0.35,0.35);
      cmd.right=cp(fwd2+steer2,-0.35,0.35);
      cmd.drill=true;
      mem.drillT+=dt;
      if(mem.drillT>25){
        var ts2=gs(mem,mem.tgtId);
        if(ts2)ts2.sampled=true;
        mem.state='PLAN';mem.drillT=0;cmd.drill=false;
      }
    }
  }

  if(mem.state==='DOCK'){
    var dBase2=ds(obs.x,obs.y,mem.bx,mem.by);
    if(dBase2>5){mem.state='PLAN';}
    else{
      if(!obs.docked&&dBase2>1.5){
        var ang=Math.atan2(mem.by-obs.y,mem.bx-obs.x)/DR;
        var steer3=cp(w(ang-(obs.heading||0))*0.015,-0.15,0.15);
        cmd.left=cp(0.12-steer3,-0.2,0.2);
        cmd.right=cp(0.12+steer3,-0.2,0.2);
      }
      if(mem.dockT<0){mem.dockT=obs.t;mem.dockB=obs.battery||1;}
      if((obs.carried||0)===0){
        var charged=(obs.battery||0)>0.85||(obs.t-mem.dockT>50)||
          ((obs.battery||0)>mem.dockB+0.12);
        if(charged){mem.state='PLAN';mem.dockT=-1;}
      }
      if((obs.timeLeft||0)<25){cmd.left=0;cmd.right=0;}
    }
  }

  if(!isFinite(cmd.left))cmd.left=0;
  if(!isFinite(cmd.right))cmd.right=0;
  cmd.left=cp(cmd.left,-1,1);
  cmd.right=cp(cmd.right,-1,1);
  cmd.drill=!!cmd.drill;
  mem.cmdL=cmd.left;mem.cmdR=cmd.right;
  return cmd;
}

function act(obs, mem) {
  mem = mem || {};

  function finite(v) { return typeof v === "number" && isFinite(v); }
  function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function angleDiff(a, b) { return wrap(a - b); }
  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var now = finite(obs.t) ? obs.t : 0;
  var rawX = finite(obs.x) ? obs.x : 0;
  var rawY = finite(obs.y) ? obs.y : 0;
  var rawHeading = finite(obs.heading) ? wrap(obs.heading) : 0;
  var battery = finite(obs.battery) ? Math.max(0, obs.battery) : 0;
  var solar = finite(obs.solar) ? Math.max(0, obs.solar) : 0;
  var carried = finite(obs.carried) ? Math.max(0, obs.carried) : 0;
  var delivered = finite(obs.delivered) ? obs.delivered : 0;
  var first = !mem.initialized;

  if (first) {
    var mission = obs.mission || {};
    var mapSize = mission.size;
    var sx = 400, sy = 400;
    if (finite(mapSize)) {
      sx = mapSize;
      sy = mapSize;
    } else if (mapSize && typeof mapSize === "object") {
      if (finite(mapSize.width)) sx = mapSize.width;
      else if (finite(mapSize.w)) sx = mapSize.w;
      if (finite(mapSize.height)) sy = mapSize.height;
      else if (finite(mapSize.h)) sy = mapSize.h;
    }

    var base = mission.base || {};
    mem.baseX = finite(base.x) ? base.x : rawX;
    mem.baseY = finite(base.y) ? base.y : rawY;
    mem.sizeX = Math.max(20, sx);
    mem.sizeY = Math.max(20, sy);
    mem.capacity = finite(mission.capacity) ? Math.max(1, mission.capacity) : 5;
    mem.missionSeconds = finite(mission.seconds) ? mission.seconds : 1200;

    mem.candidates = [];
    var hints = mission.hints || [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi];
      if (h && finite(h.x) && finite(h.y)) {
        mem.candidates.push({
          x: h.x,
          y: h.y,
          v: finite(h.estimate) ? Math.max(0.1, h.estimate) : 1,
          status: 0
        });
      }
    }

    mem.initialized = true;
    mem.px = rawX;
    mem.py = rawY;
    mem.ph = rawHeading;
    mem.headingBias = 0;
    mem.lastRawHeading = rawHeading;
    mem.compassBadUntil = 0;

    mem.lastRawGpsX = rawX;
    mem.lastRawGpsY = rawY;
    mem.gpsRawChangeT = now;
    mem.gpsAcceptedX = rawX;
    mem.gpsAcceptedY = rawY;
    mem.gpsAcceptedT = now;
    mem.gpsStartHeading = rawHeading;
    mem.gpsIntWheel = 0;
    mem.gpsAbsWheel = 0;
    mem.gpsIntTurn = 0;
    mem.gpsFrozen = false;
    mem.slipFactor = 1;

    mem.gainL = 2.5;
    mem.gainR = 2.5;
    mem.prevLeftCmd = 0;
    mem.prevRightCmd = 0;
    mem.prevDrillCmd = 0;

    mem.speedAvg = 1.5;
    mem.eBase = 0.0008;
    mem.eRecent = 0.0008;
    mem.idleRate = 0.00003;
    mem.drillRate = 0.00035;
    mem.energyDist = 0;
    mem.energyTime = 0;
    mem.energyUsed = 0;

    mem.mode = "explore";
    mem.job = null;
    mem.siteGoal = null;
    mem.dockStart = now - 5;
    mem.sciPeaks = [];
    mem.searched = [];
    mem.sweepPoints = null;
    mem.navTrack = null;
    mem.forceSide = 0;
    mem.forceUntil = 0;
    mem.avoidSign = 0;
    mem.avoidUntil = 0;
    mem.bumpUntil = 0;
    mem.bumpSign = 1;
    mem.prevBumped = false;

    mem.rayPrev = [];
    mem.raySame = [];
    mem.rayTrack = [];
    mem.rayTurn = [];
    mem.rayStuck = [];
    mem.rayVals = [];
    mem.rayFaultN = 0;

    mem.prevT = now;
    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.lastDelivered = delivered;
  }

  var dt = first ? 0.1 : clamp(now - (finite(mem.prevT) ? mem.prevT : now - 0.1), 0.05, 0.3);
  var wl = finite(obs.wheelLeft) ? obs.wheelLeft : 0;
  var wr = finite(obs.wheelRight) ? obs.wheelRight : 0;
  var pitch = finite(obs.pitch) ? obs.pitch : 0;
  var vWheel = (wl + wr) * 0.5;
  var wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;

  if (!first) {
    if (Math.abs(mem.prevLeftCmd) > 0.2 && wl * mem.prevLeftCmd > 0.02) {
      var gl = Math.abs(wl / mem.prevLeftCmd);
      if (gl > 0.35 && gl < 5.5) {
        var al = gl < mem.gainL * 0.65 ? 0.12 : 0.025;
        mem.gainL = clamp(mem.gainL + al * (gl - mem.gainL), 0.45, 5.2);
      }
    }
    if (Math.abs(mem.prevRightCmd) > 0.2 && wr * mem.prevRightCmd > 0.02) {
      var gr = Math.abs(wr / mem.prevRightCmd);
      if (gr > 0.35 && gr < 5.5) {
        var ar = gr < mem.gainR * 0.65 ? 0.12 : 0.025;
        mem.gainR = clamp(mem.gainR + ar * (gr - mem.gainR), 0.45, 5.2);
      }
    }
  }

  var oldX = mem.px;
  var oldY = mem.py;
  var oldPh = mem.ph;
  var turnDeg = (wr - wl) / 0.6 * dt * 180 / Math.PI;
  var phPred = wrap(oldPh + turnDeg);
  var compassDelta = angleDiff(rawHeading, mem.lastRawHeading);

  if (!first && Math.abs(compassDelta) > 45 && Math.abs(turnDeg) < 25) {
    mem.compassBadUntil = now + 12;
  }

  var ph = phPred;
  if (now >= mem.compassBadUntil) {
    var compassTarget = wrap(rawHeading + mem.headingBias);
    var compassResidual = angleDiff(compassTarget, phPred);
    if (Math.abs(compassResidual) < 70) {
      var hAlpha = Math.abs(vWheel) < 0.1 && Math.abs(turnDeg) < 2 ? 0.18 : 0.08;
      ph = wrap(phPred + clamp(hAlpha * compassResidual, -5, 5));
    }
  }

  var midRad = (oldPh + phPred) * 0.5 * Math.PI / 180;
  var px = oldX + vWheel * dt * Math.cos(midRad);
  var py = oldY + vWheel * dt * Math.sin(midRad);

  mem.gpsIntWheel += vWheel * dt;
  mem.gpsAbsWheel += Math.abs(vWheel) * dt;
  mem.gpsIntTurn += turnDeg;

  var gpsStep = 0;
  var gpsStepDt = 0;
  var gpsAccepted = false;

  if (finite(obs.x) && finite(obs.y)) {
    var rawMove = dist(rawX, rawY, mem.lastRawGpsX, mem.lastRawGpsY);
    if (rawMove > 0.025) {
      var rawDt = Math.max(0.1, now - mem.gpsRawChangeT);
      mem.gpsRawChangeT = now;

      var inBounds = rawX >= -5 && rawY >= -5 &&
        rawX <= mem.sizeX + 5 && rawY <= mem.sizeY + 5;
      var plausible = rawMove <= 10 + 3.5 * rawDt;

      if (inBounds && plausible) {
        var staleTime = now - mem.gpsAcceptedT;
        var wasFrozen = staleTime > 2.5 && mem.gpsAbsWheel > 2.5;
        var innovation = dist(rawX, rawY, px, py);

        if (wasFrozen || innovation < 10) {
          var acceptAlpha = wasFrozen ? 0.72 : (innovation > 5 ? 0.14 : 0.30);

          if (mem.gpsAcceptedT > 0 || !first) {
            var gpsDx = rawX - mem.gpsAcceptedX;
            var gpsDy = rawY - mem.gpsAcceptedY;
            var dGps = Math.sqrt(gpsDx * gpsDx + gpsDy * gpsDy);
            var acceptedDt = Math.max(0.1, now - mem.gpsAcceptedT);

            if (dGps > 2.5 && mem.gpsAbsWheel > 2.5 &&
                mem.gpsIntWheel > 1 && Math.abs(mem.gpsIntTurn) < 18) {
              var course = Math.atan2(gpsDy, gpsDx) * 180 / Math.PI;
              var hDelta = angleDiff(rawHeading, mem.gpsStartHeading);
              var avgCompass = wrap(mem.gpsStartHeading + hDelta * 0.5);
              var biasErr = angleDiff(course, avgCompass);
              mem.headingBias = wrap(mem.headingBias + clamp(biasErr * 0.08, -2, 2));
            }

            if (acceptedDt > 0.5 && dGps > 0.5 && mem.gpsAbsWheel > 1.0 &&
                Math.abs(mem.gpsIntTurn) < 35) {
              var slip = clamp(dGps / mem.gpsAbsWheel, 0.3, 1.0);
              if (slip < mem.slipFactor) {
                mem.slipFactor = clamp(mem.slipFactor * 0.78 + slip * 0.22, 0.3, 1.0);
              } else {
                mem.slipFactor = clamp(mem.slipFactor * 0.97 + slip * 0.03, 0.3, 1.0);
              }
              gpsStep = dGps;
              gpsStepDt = acceptedDt;
            }
          }

          px += (rawX - px) * acceptAlpha;
          py += (rawY - py) * acceptAlpha;
          mem.gpsAcceptedX = rawX;
          mem.gpsAcceptedY = rawY;
          mem.gpsAcceptedT = now;
          mem.gpsStartHeading = rawHeading;
          mem.gpsIntWheel = 0;
          mem.gpsAbsWheel = 0;
          mem.gpsIntTurn = 0;
          mem.gpsFrozen = false;
          gpsAccepted = true;
        }
      }
    }

    mem.lastRawGpsX = rawX;
    mem.lastRawGpsY = rawY;
  }

  if (now - mem.gpsAcceptedT > 3 && mem.gpsAbsWheel > 3) {
    mem.gpsFrozen = true;
  }

  mem.px = px;
  mem.py = py;
  mem.ph = ph;
  mem.lastRawHeading = rawHeading;
  mem.poseStep = dist(oldX, oldY, px, py);
  mem.odomStep = wheelTravel * Math.max(0.3, mem.slipFactor);

  if (wheelTravel > 0.04 && Math.abs(vWheel) > 0.12 && !obs.docked) {
    var groundSpeed = Math.abs(vWheel) * mem.slipFactor;
    mem.speedAvg = clamp(mem.speedAvg * 0.94 + groundSpeed * 0.06, 0.45, 3.0);
  }

  var rays = obs.rays || [];
  mem.rayFaultN = 0;
  for (var ri = 0; ri < 9; ri++) {
    var rv = ri < rays.length && finite(rays[ri]) ? clamp(rays[ri], 0, 15) : 15;
    if (typeof mem.raySame[ri] !== "number") {
      mem.raySame[ri] = 0;
      mem.rayTrack[ri] = 0;
      mem.rayTurn[ri] = 0;
      mem.rayStuck[ri] = false;
      mem.rayPrev[ri] = rv;
    } else if (Math.abs(rv - mem.rayPrev[ri]) < 0.04) {
      mem.raySame[ri] += dt;
      mem.rayTrack[ri] += wheelTravel;
      mem.rayTurn[ri] += Math.abs(turnDeg);
    } else {
      if (mem.rayStuck[ri] && Math.abs(rv - mem.rayPrev[ri]) > 0.5) {
        mem.rayStuck[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayTrack[ri] = 0;
      mem.rayTurn[ri] = 0;
    }

    if (!mem.rayStuck[ri] && rv < 14.8 &&
        mem.raySame[ri] > 10 &&
        (mem.rayTrack[ri] > 8 || mem.rayTurn[ri] > 70)) {
      mem.rayStuck[ri] = true;
    }
    if (mem.rayStuck[ri]) mem.rayFaultN++;
    mem.rayPrev[ri] = rv;
    mem.rayVals[ri] = mem.rayStuck[ri] ? 15 : rv;
  }

  var grossEnergy = 0;
  if (!first && finite(mem.prevBattery)) {
    grossEnergy = Math.max(0, mem.prevBattery - battery + solar * dt);
  }

  if (!obs.docked && !first) {
    mem.energyUsed += grossEnergy;
    mem.energyTime += dt;
    var ed = wheelTravel * Math.max(0.3, mem.slipFactor);
    if (ed < 0.05 && gpsAccepted && gpsStepDt > 0.5) ed = Math.min(1.5, gpsStep);
    mem.energyDist += ed;

    if (mem.prevDrillCmd > 0.5 && grossEnergy > 0) {
      var dr = grossEnergy / Math.max(0.05, dt);
      if (dr < 0.02) {
        mem.drillRate = clamp(mem.drillRate * 0.8 + dr * 0.2, 0.00005, 0.02);
      }
    }

    if (mem.energyDist >= 7 || mem.energyTime >= 25) {
      if (mem.energyDist >= 2) {
        var netUse = Math.max(0, mem.energyUsed - mem.idleRate * mem.energyTime);
        var currentLoad = 1 + 0.14 * carried;
        var rate = netUse / Math.max(1, mem.energyDist) / currentLoad;
        rate = clamp(rate, 0.00012, 0.025);
        if (rate > mem.eBase * 1.5) {
          mem.eBase = clamp(mem.eBase * 0.48 + rate * 0.52, 0.00012, 0.025);
        } else {
          mem.eBase = clamp(mem.eBase * 0.88 + rate * 0.12, 0.00012, 0.025);
        }
        mem.eRecent = clamp(mem.eRecent * 0.65 + rate * 0.35, 0.00012, 0.025);
      } else if (mem.energyTime > 5 && mem.prevDrillCmd < 0.5) {
        var idle = mem.energyUsed / Math.max(1, mem.energyTime);
        if (idle < 0.01) {
          mem.idleRate = clamp(mem.idleRate * 0.8 + idle * 0.2, 0.000005, 0.005);
        }
      }
      mem.energyDist = 0;
      mem.energyTime = 0;
      mem.energyUsed = 0;
    }
  } else if (obs.docked) {
    mem.energyDist = 0;
    mem.energyTime = 0;
    mem.energyUsed = 0;
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.prevT = now;

  var timeLeft = finite(obs.timeLeft)
    ? Math.max(0, obs.timeLeft)
    : Math.max(0, mem.missionSeconds - now);

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;
  var science = finite(obs.science) ? Math.max(0, obs.science) : 0;

  if (science > 0) {
    var nearestPeak = -1;
    var nearestPeakDist = 1e9;
    for (var spi = 0; spi < mem.sciPeaks.length; spi++) {
      var pd = dist(mem.px, mem.py, mem.sciPeaks[spi].x, mem.sciPeaks[spi].y);
      if (pd < nearestPeakDist) {
        nearestPeakDist = pd;
        nearestPeak = spi;
      }
    }
    if (nearestPeak >= 0 && nearestPeakDist < 13) {
      if (science > mem.sciPeaks[nearestPeak].s) {
        mem.sciPeaks[nearestPeak].s = science;
        mem.sciPeaks[nearestPeak].x = mem.px;
        mem.sciPeaks[nearestPeak].y = mem.py;
        mem.sciPeaks[nearestPeak].t = now;
      }
    } else {
      var lastRecDist = dist(mem.px, mem.py, mem.lastSciRecordX, mem.lastSciRecordY);
      if (lastRecDist > 6 || now - mem.lastSciRecordT > 15) {
        mem.sciPeaks.push({ x: mem.px, y: mem.py, s: science, used: false, t: now });
        mem.lastSciRecordX = mem.px;
        mem.lastSciRecordY = mem.py;
        mem.lastSciRecordT = now;
        if (mem.sciPeaks.length > 20) {
          mem.sciPeaks.sort(function(a, b) { return b.s - a.s; });
          mem.sciPeaks.length = 20;
        }
      }
    }
  }

  function addSearched(x, y) {
    for (var i = 0; i < mem.searched.length; i++) {
      if (dist(x, y, mem.searched[i].x, mem.searched[i].y) < 8) return;
    }
    mem.searched.push({ x: x, y: y });
    if (mem.searched.length > 100) mem.searched.shift();
  }

  function completeJob() {
    var j = mem.job;
    if (!j) return;
    if (j.kind === "hint" && mem.candidates[j.idx]) {
      mem.candidates[j.idx].status = 2;
    } else if (j.kind === "science" && mem.sciPeaks[j.peakIndex]) {
      mem.sciPeaks[j.peakIndex].used = true;
    } else if (j.kind === "sweep" && mem.sweepPoints && mem.sweepPoints[j.sweepIndex]) {
      mem.sweepPoints[j.sweepIndex].used = true;
    }
    addSearched(j.cx, j.cy);
    mem.job = null;
    mem.navTrack = null;
  }

  function finishSample() {
    var s = mem.siteGoal;
    if (!s) return;
    var sx = finite(s.x) ? s.x : mem.px;
    var sy = finite(s.y) ? s.y : mem.py;

    if (mem.job && mem.job.kind === "hint" &&
        dist(mem.job.cx, mem.job.cy, sx, sy) < 33) {
      completeJob();
    } else if (mem.job && mem.job.kind === "science" &&
               dist(mem.job.cx, mem.job.cy, sx, sy) < 30) {
      completeJob();
    }

    var best = -1, bestD = 1e9;
    for (var ci = 0; ci < mem.candidates.length; ci++) {
      if (mem.candidates[ci].status === 2) continue;
      var cd = dist(mem.candidates[ci].x, mem.candidates[ci].y, sx, sy);
      if (cd < bestD) {
        bestD = cd;
        best = ci;
      }
    }
    if (best >= 0 && bestD < 28) {
      mem.candidates[best].status = 2;
      addSearched(mem.candidates[best].x, mem.candidates[best].y);
      if (mem.job && mem.job.kind === "hint" && mem.job.idx === best) {
        completeJob();
      }
    }

    for (var pi = 0; pi < mem.sciPeaks.length; pi++) {
      if (dist(mem.sciPeaks[pi].x, mem.sciPeaks[pi].y, sx, sy) < 22) {
        mem.sciPeaks[pi].used = true;
      }
    }
    mem.siteGoal = null;
  }

  var drillingNow = finite(obs.drilling) ? obs.drilling : 0;
  if (mem.siteGoal) {
    var carriedAfterSample = carried > mem.siteGoal.carry0 + 0.1;
    var deliveredAfterSample = delivered > mem.siteGoal.delivered0 + 0.000001;
    var drillFinished = mem.siteGoal.phase === "drill" &&
      drillingNow >= 5.8 && !siteObs && now - mem.siteGoal.started > 5.5;
    if (carriedAfterSample || deliveredAfterSample || drillFinished) {
      finishSample();
    }
  }

  if (mem.siteGoal && siteObs &&
      finite(siteObs.distance) && finite(siteObs.bearing)) {
    var sr = Math.max(0, siteObs.distance);
    var sa = (mem.ph + siteObs.bearing) * Math.PI / 180;
    mem.siteGoal.x = mem.px + sr * Math.cos(sa);
    mem.siteGoal.y = mem.py + sr * Math.sin(sa);
    mem.siteGoal.value = finite(siteObs.value) ? siteObs.value : mem.siteGoal.value;
    mem.siteGoal.lastSeen = now;
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped) {
    var leftOpen = Math.max(mem.rayVals[5] || 0, mem.rayVals[6] || 0, mem.rayVals[7] || 0);
    var rightOpen = Math.max(mem.rayVals[1] || 0, mem.rayVals[2] || 0, mem.rayVals[3] || 0);
    mem.bumpSign = leftOpen >= rightOpen ? 1 : -1;
    mem.bumpUntil = now + 1.2;
  }
  mem.prevBumped = bumped;

  function baseDistance() {
    return dist(mem.px, mem.py, mem.baseX, mem.baseY);
  }

  function atBase() {
    if (obs.docked) return true;
    if (obs.beacon && finite(obs.beacon.distance)) {
      return obs.beacon.distance <= 2.5;
    }
    return baseDistance() <= 2.0;
  }

  function rateBase() {
    return Math.max(0.00035, mem.eBase || 0.0008, (mem.eRecent || 0.0008) * 0.85);
  }

  function travelSpeed() {
    return clamp((mem.speedAvg || 1.5) * 0.78, 0.72, 1.65);
  }

  function returnTime(d) {
    return Math.max(0, d) / travelSpeed() * 1.22 + 20;
  }

  function energyNeed(d, n, seconds, drillSeconds) {
    var loadRate = rateBase() * (1 + 0.14 * Math.max(0, n));
    return Math.max(0, d) * loadRate * 1.62 +
      Math.max(0, seconds || 0) * Math.max(0.000005, mem.idleRate || 0.00003) * 1.2 +
      Math.max(0, drillSeconds || 0) * Math.max(0.00005, mem.drillRate || 0.00035) +
      0.04;
  }

  function clampMapX(x) { return clamp(x, 2, mem.sizeX - 2); }
  function clampMapY(y) { return clamp(y, 2, mem.sizeY - 2); }

  function ringPoint(j, radius, index) {
    var a = (index % 12) * Math.PI / 6;
    return {
      x: clampMapX(j.cx + radius * Math.cos(a)),
      y: clampMapY(j.cy + radius * Math.sin(a))
    };
  }

  function jobTarget(j) {
    if (j.stage === 1) return ringPoint(j, 14, j.index);
    if (j.stage === 2) {
      return {
        x: clampMapX(j.cx + 26 * Math.cos(j.rayDir)),
        y: clampMapY(j.cy + 26 * Math.sin(j.rayDir))
      };
    }
    if (j.stage === 3) {
      return {
        x: clampMapX(j.cx + 32 * Math.cos(j.rayDir)),
        y: clampMapY(j.cy + 32 * Math.sin(j.rayDir))
      };
    }
    return { x: j.cx, y: j.cy };
  }

  function jobKey(j) {
    if (!j) return "none";
    return "job:" + j.kind + ":" + j.idx + ":" + j.stage + ":" +
      (j.stage === 1 ? j.index : 0);
  }

  function jobPlan() {
    var j = mem.job;
    if (!j) return null;
    var target = jobTarget(j);
    var dTarget = dist(mem.px, mem.py, target.x, target.y);
    var remain = 0;
    if (j.stage === 0) remain = 105;
    else if (j.stage === 1) remain = Math.max(0, 12 - j.index) * 7.5 + 16;
    else if (j.stage === 2) remain = 14;
    else remain = 7;
    var back = dist(j.cx, j.cy, mem.baseX, mem.baseY);
    var total = dTarget + remain + back;
    var speed = travelSpeed();
    var tripSeconds = total / speed * 1.28 + 38;
    return {
      target: target,
      distance: total,
      seconds: tripSeconds,
      need: energyNeed(total, carried, tripSeconds, 6)
    };
  }

  function nearSearched(x, y, radius) {
    for (var i = 0; i < mem.searched.length; i++) {
      if (dist(x, y, mem.searched[i].x, mem.searched[i].y) < radius) return true;
    }
    return false;
  }

  function createJob(kind, x, y, extra) {
    var j = {
      kind: kind,
      cx: clampMapX(x),
      cy: clampMapY(y),
      stage: 0,
      index: 0,
      centerSci: 0,
      bestSci: 0,
      bestX: clampMapX(x),
      bestY: clampMapY(y),
      innerBest: 0,
      rayDir: 0,
      started: now
    };
    if (extra) {
      for (var k in extra) {
        if (Object.prototype.hasOwnProperty.call(extra, k)) j[k] = extra[k];
      }
    }
    mem.job = j;
  }

  function ensureJob() {
    if (mem.job) return true;

    var bestIndex = -1;
    var bestScore = -1;
    var speed = travelSpeed();

    for (var i = 0; i < mem.candidates.length; i++) {
      var c = mem.candidates[i];
      if (c.status !== 0) continue;
      var d1 = dist(mem.px, mem.py, c.x, c.y);
      var d2 = dist(c.x, c.y, mem.baseX, mem.baseY);
      var total = d1 + 105 + d2;
      var seconds = total / speed * 1.28 + 38;
      var need = energyNeed(total, carried, seconds, 6);
      if (need > 0.97 || seconds > timeLeft - 12) continue;
      var score = (Math.max(0.1, c.v) + 0.25) /
        (38 + d1 + 0.62 * d2 + 0.35 * 105);
      if (score > bestScore) {
        bestScore = score;
        bestIndex = i;
      }
    }

    if (bestIndex >= 0) {
      var chosen = mem.candidates[bestIndex];
      chosen.status = 1;
      createJob("hint", chosen.x, chosen.y, { idx: bestIndex });
      return true;
    }

    var peakIndex = -1;
    var peakScore = -1;
    for (var p = 0; p < mem.sciPeaks.length; p++) {
      var peak = mem.sciPeaks[p];
      if (peak.used || nearSearched(peak.x, peak.y, 26)) continue;
      var pd1 = dist(mem.px, mem.py, peak.x, peak.y);
      var pd2 = dist(peak.x, peak.y, mem.baseX, mem.baseY);
      var ptotal = pd1 + 95 + pd2;
      var pseconds = ptotal / speed * 1.28 + 38;
      var pneed = energyNeed(ptotal, carried, pseconds, 6);
      if (pneed > 0.97 || pseconds > timeLeft - 12) continue;
      var pscore = peak.s / (35 + pd1 + 0.62 * pd2);
      if (pscore > peakScore) {
        peakScore = pscore;
        peakIndex = p;
      }
    }

    if (peakIndex >= 0) {
      var selectedPeak = mem.sciPeaks[peakIndex];
      createJob("science", selectedPeak.x, selectedPeak.y, { peakIndex: peakIndex });
      return true;
    }

    if (!mem.sweepPoints) {
      mem.sweepPoints = [];
      for (var gx = 35; gx <= mem.sizeX - 25; gx += 65) {
        for (var gy = 35; gy <= mem.sizeY - 25; gy += 65) {
          mem.sweepPoints.push({ x: gx, y: gy, used: false });
        }
      }
    }

    var sweepIndex = -1;
    var sweepScore = -1;
    for (var si = 0; si < mem.sweepPoints.length; si++) {
      var sp = mem.sweepPoints[si];
      if (sp.used || nearSearched(sp.x, sp.y, 25)) continue;
      var sd1 = dist(mem.px, mem.py, sp.x, sp.y);
      var sd2 = dist(sp.x, sp.y, mem.baseX, mem.baseY);
      var stotal = sd1 + 80 + sd2;
      var sseconds = stotal / speed * 1.28 + 38;
      var sneed = energyNeed(stotal, carried, sseconds, 6);
      if (sneed > 0.97 || sseconds > timeLeft - 12) continue;
      var sscore = 1 / (45 + sd1 + 0.5 * sd2);
      if (sscore > sweepScore) {
        sweepScore = sscore;
        sweepIndex = si;
      }
    }

    if (sweepIndex >= 0) {
      var sw = mem.sweepPoints[sweepIndex];
      createJob("sweep", sw.x, sw.y, { sweepIndex: sweepIndex });
      return true;
    }
    return false;
  }

  function discardJob() {
    var j = mem.job;
    if (!j) return;
    if (j.kind === "hint" && mem.candidates[j.idx]) {
      mem.candidates[j.idx].status = 2;
    } else if (j.kind === "science" && mem.sciPeaks[j.peakIndex]) {
      mem.sciPeaks[j.peakIndex].used = true;
    } else if (j.kind === "sweep" && mem.sweepPoints && mem.sweepPoints[j.sweepIndex]) {
      mem.sweepPoints[j.sweepIndex].used = true;
    }
    mem.job = null;
    mem.navTrack = null;
  }

  function recoverJobStall() {
    var j = mem.job;
    if (!j) return;
    var key = jobKey(j);
    if (!mem.navTrack || mem.navTrack.key !== key || mem.navTrack.stall < 35) return;

    if (j.stage === 0) {
      j.stage = 1;
      j.index = 0;
      j.centerSci = science;
      j.bestSci = science;
      j.bestX = mem.px;
      j.bestY = mem.py;
    } else if (j.stage === 1) {
      j.index++;
    } else if (j.stage === 2) {
      j.stage = 3;
    } else {
      completeJob();
    }
    mem.navTrack = null;
  }

  function advanceJob() {
    var j = mem.job;
    if (!j) return;

    var centerDistance = dist(mem.px, mem.py, j.cx, j.cy);
    if (j.stage === 0 && centerDistance <= 5) {
      j.centerSci = science;
      j.bestSci = science;
      j.bestX = mem.px;
      j.bestY = mem.py;
      if (j.kind === "sweep" && science <= 0) {
        completeJob();
        return;
      }
      j.stage = 1;
      j.index = 0;
      return;
    }

    if (j.stage === 1 && centerDistance < 50 && science > j.bestSci) {
      j.bestSci = science;
      j.bestX = mem.px;
      j.bestY = mem.py;
    }

    if (j.stage === 1) {
      var guard = 0;
      while (j.index < 12 && guard++ < 12) {
        var rp = ringPoint(j, 14, j.index);
        if (dist(mem.px, mem.py, rp.x, rp.y) <= 3.3) {
          j.index++;
        } else {
          break;
        }
      }
      if (j.index >= 12) {
        j.innerBest = j.bestSci;
        var tolerance = Math.max(0.000001, Math.abs(j.centerSci) * 0.025);
        if (j.bestSci > j.centerSci + tolerance) {
          var vx = j.bestX - j.cx;
          var vy = j.bestY - j.cy;
          if (Math.sqrt(vx * vx + vy * vy) > 2) {
            j.rayDir = Math.atan2(vy, vx);
            j.stage = 2;
          } else {
            completeJob();
          }
        } else {
          completeJob();
        }
      }
      return;
    }

    if (j.stage === 2) {
      var outer = jobTarget(j);
      if (dist(mem.px, mem.py, outer.x, outer.y) <= 3.3) {
        var tol2 = Math.max(0.000001, Math.abs(j.innerBest) * 0.025);
        if (science > j.innerBest + tol2) {
          j.stage = 3;
        } else {
          completeJob();
        }
      }
      return;
    }

    if (j.stage === 3) {
      var farther = jobTarget(j);
