    if (frontRange < 4.3 && Math.abs(rel) < 75) {
      var frontCap = Math.sqrt(2 * 0.42 * Math.max(0, frontRange - 0.85));
      vSet = Math.min(vSet, frontCap);
    }

    if (mem.rayFaultN >= 4) vSet = Math.min(vSet, 1.5);
    if (mem.slipFactor < 0.8) vSet *= clamp(0.72 + mem.slipFactor * 0.3, 0.72, 1);
    if (Math.abs(pitch) > 18) vSet *= 0.78;
    if (pitch < -12) vSet *= 0.82;

    var ae = Math.abs(rel);
    if (ae > 100) vSet = 0;
    else if (ae > 70) vSet = Math.min(vSet, 0.45);
    else if (ae > 40) vSet *= 0.76;

