        s.still = 0;
        if (sb.visible) return driveNav(sb.bearing, d, 1.0, 1.25, "site");
        return driveNav(sb.bearing, d, 1.0, 1.1, "site");
      }

      if (now < mem.bumpUntil) {
        s.still = 0;
        return holdStill(false);
      }

      var slow = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
      if (slow) s.still += dt;
      else s.still = 0;

