      return driveToBase();
    }

    if (carried > 0) {
      return holdStill(false);
    }

    if (mem.siteGoal && mem.siteGoal.phase === "approach") {
      var sdist = siteDistanceAndBearing().distance;
      if (now - mem.siteGoal.lastSeen > 6 && !siteObs) {
        mem.siteGoal = null;
      } else if (canSampleAt(sdist)) {
