      tries++;
    }

    if (!mem.job) return holdStill(false);
    var plan = jobPlan();
    if (!plan || timeLeft <= plan.seconds + 12) return holdStill(false);
    if (battery >= plan.need + 0.035) {
      setMode("explore");
    }
    return holdStill(false);
  }

  if (mem.mode === "return" && atBase()) setMode("dock");
  if (mem.mode === "explore" && obs.docked &&
      (carried > 0 || battery < 0.92)) setMode("dock");
  if (mem.mode === "dock" && !atBase() && !obs.docked) setMode("return");

  if (mem.siteGoal && mem.siteGoal.phase === "drill") {
    return siteAction();
  }

  if (mem.mode === "return") {
    return driveToBase();
  }

  if (mem.mode === "dock") {
    return handleDock();
  }

  var dBase = baseDistance();
  var retT = returnTime(dBase);
  var backNeed = energyNeed(dBase, carried, retT, 0);

  if (carried >= mem.capacity ||
      timeLeft < retT + 22 ||
      battery < backNeed + 0.025) {
    setMode("return");
    if (atBase()) {
      setMode("dock");
      return handleDock();
    }
    return driveToBase();
  }

  if (mem.siteGoal && mem.siteGoal.phase === "approach") {
    var activeSiteDist = siteDistanceAndBearing().distance;
    if (!canSampleAt(activeSiteDist)) {
