    }
    setMode("return");
    if (atBase()) {
      setMode("dock");
      return handleDock();
    }
    return driveToBase();
  }

  if (mem.job) recoverJobStall();
  if (mem.job) advanceJob();
  if (!mem.job) ensureJob();
  if (mem.job) advanceJob();

  if (!mem.job) {
    setMode("return");
    if (atBase()) {
      setMode("dock");
      return handleDock();
    }
    return driveToBase();
  }

  var currentPlan = jobPlan();
  if (!currentPlan ||
      battery < currentPlan.need + 0.025 ||
      timeLeft < currentPlan.seconds + 12) {
    if (atBase() && obs.docked) {
      setMode("dock");
      return handleDock();
    }
    setMode("return");
    if (atBase()) {
      setMode("dock");
      return handleDock();
    }
    return driveToBase();
  }

  var target = jobTarget(mem.job);
  var targetDistance = dist(mem.px, mem.py, target.x, target.y);
  var stopR = mem.job.stage === 0 ? 4.5 : 3.0;
  var navKey = jobKey(mem.job);
