        continue;
      }
      consider("hint", ci, c.x, c.y, c.v, c.v + 0.25);
    }

    if (!best) {
      for (var pi = 0; pi < mem.peaks.length; pi++) {
        var p = mem.peaks[pi];
        if (p.used || nearSearched(p.x, p.y, 18)) continue;
        var matchedHint = false;
        for (var cj = 0; cj < mem.candidates.length; cj++) {
          if (mem.candidates[cj].status === 2 &&
              distance(p.x, p.y, mem.candidates[cj].x, mem.candidates[cj].y) < 20) {
            matchedHint = true;
            break;
          }
        }
        if (matchedHint) continue;
        consider("peak", pi, p.x, p.y, p.s, 0.5 + p.s);
      }
    }

    if (!best) {
      for (var gi = 0; gi < mem.grid.length; gi++) {
        var g = mem.grid[gi];
        if (g.used || nearSearched(g.x, g.y, 20)) continue;
        consider("grid", gi, g.x, g.y, 0.2, 0.22);
      }
    }

    if (!best) return false;
    createJob(best.kind, best.idx, best.x, best.y, best.value);
    if (best.kind === "hint" && mem.candidates[best.idx]) {
      mem.candidates[best.idx].status = 1;
    }
    if (best.kind === "peak" && mem.peaks[best.idx]) {
      mem.peaks[best.idx].used = true;
    }
    if (best.kind === "grid" && mem.grid[best.idx]) {
      mem.grid[best.idx].used = true;
    }
    return true;
  }

  function advanceJob() {
    var j = mem.job;
    if (!j) return;

    if (distance(mem.px, mem.py, j.cx, j.cy) < 28 &&
        science > j.bestS) {
      j.bestS = science;
      j.bestX = mem.px;
      j.bestY = mem.py;
    }

    var key = jobKey(j);
    if (mem.navTrack &&
        mem.navTrack.key === key &&
        mem.navTrack.stall > 35) {
      if (j.phase === 0) {
        j.phase = 1;
        j.index = 0;
      } else if (j.phase === 1) {
        j.index++;
        if (j.index >= 8) {
          j.phase = 3;
          j.index = 0;
        }
      } else if (j.phase === 2) {
        j.phase = 3;
        j.index = 0;
      } else {
        j.index++;
        if (j.index >= 12) {
          finishJob();
          return;
        }
      }
      mem.navTrack = null;
    }

    if (!mem.job) return;
    j = mem.job;
    var target = jobTarget(j);
    var d = distance(mem.px, mem.py, target.x, target.y);
    var stop = j.phase === 0 ? 4.0 : 2.8;
    if (d > stop) return;

    if (j.phase === 0) {
      j.centerS = science;
      if (science > j.bestS) {
        j.bestS = science;
        j.bestX = mem.px;
        j.bestY = mem.py;
      }
      if (j.kind === "grid" && science < 0.006) {
        finishJob();
        return;
      }
      j.phase = 1;
      j.index = 0;
      mem.navTrack = null;
      return;
    }

    if (j.phase === 1) {
      j.index++;
      if (j.index >= 8) {
        var bx = j.bestX - j.cx;
        var by = j.bestY - j.cy;
        var br = Math.sqrt(bx * bx + by * by);
        var gain = j.bestS - j.centerS;
        if (br > 2.5 &&
            gain > Math.max(0.012, Math.abs(j.centerS) * 0.06)) {
          j.phase = 2;
          j.index = 0;
        } else {
          j.phase = 3;
          j.index = 0;
        }
      }
      mem.navTrack = null;
      return;
    }

    if (j.phase === 2) {
      j.phase = 3;
      j.index = 0;
      mem.navTrack = null;
      return;
    }

    j.index++;
    if (j.index >= 12) {
      finishJob();
      return;
    }
    mem.navTrack = null;
  }

  function canSampleAt(siteDistance) {
    if (carried >= mem.capacity) return false;
    var dBase = baseDistance();
    var retT = returnTime(dBase);
    if (timeLeft < retT + 12) return false;
    var approach = Math.min(10, Math.max(0, siteDistance || 0));
    var futureReturn = energyCost(
      dBase,
      carried + 1,
      retT + 10,
      6,
      1.9
    );
    var approachNeed = energyCost(
      approach,
      carried,
      approach / planningSpeed() + 5,
      0,
      1.35
    );
    return battery > futureReturn + approachNeed + 0.012;
  }

  function beginSite(s) {
    if (!s || !finite(s.distance) || !finite(s.bearing)) return false;
    var d = Math.max(0, s.distance);
    if (!canSampleAt(d)) return false;
    var a = (mem.ph + s.bearing) * Math.PI / 180;
    mem.siteGoal = {
      x: mem.px + d * Math.cos(a),
      y: mem.py + d * Math.sin(a),
      value: finite(s.value) ? s.value : 0,
      phase: "approach",
      carry0: carried,
      delivered0: delivered,
      started: now,
      lastSeen: now,
      still: 0
    };
    return true;
  }
  function siteDistanceAndBearing() {
    var s = mem.siteGoal;
    if (siteObs) {
      return {
        distance: Math.max(0, siteObs.distance),
        bearing: siteObs.bearing,
        visible: true
      };
    }
    var dx = s.x - mem.px;
    var dy = s.y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var b = d > 0.01
      ? angleDiff(Math.atan2(dy, dx) * 180 / Math.PI, mem.ph)
      : 0;
    return { distance: d, bearing: b, visible: false };
  }
  function finishSample() {
    var s = mem.siteGoal;
    if (!s) return;
    var sx = finite(s.x) ? s.x : mem.px;
    var sy = finite(s.y) ? s.y : mem.py;

    var nearest = -1;
    var nearestD = 1e9;
    for (var ci = 0; ci < mem.candidates.length; ci++) {
      if (mem.candidates[ci].status === 2) continue;
      var d = distance(
        sx,
        sy,
        mem.candidates[ci].x,
        mem.candidates[ci].y
      );
      if (d < nearestD) {
        nearestD = d;
        nearest = ci;
      }
    }
    if (nearest >= 0 && nearestD < 25) {
      mem.candidates[nearest].status = 2;
    }

    if (mem.job &&
        distance(sx, sy, mem.job.cx, mem.job.cy) < 28) {
      finishJob();
    }
    addSearched(sx, sy);
    mem.siteGoal = null;
  }
  function siteAction() {
    var s = mem.siteGoal;
    if (!s) return null;

    if (s.phase === "approach" &&
        !siteObs &&
        now - s.lastSeen > 8) {
      mem.siteGoal = null;
      return null;
    }

    var sb = siteDistanceAndBearing();
    var d = sb.distance;

    if (s.phase === "approach") {
      if (d > 1.22) {
        return driveBearing(sb.bearing, d, 1.0, 1.0, "site");
      }
      s.phase = "drill";
      s.still = 0;
    }

    if (s.phase === "drill") {
      if (d > 1.48) {
        s.phase = "approach";
        s.still = 0;
        return driveBearing(sb.bearing, d, 1.0, 0.9, "site");
      }

      var slow = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
      if (slow) s.still += dt;
      else s.still = 0;

      var drillOn =
        d <= 1.48 &&
        slow &&
        (s.still >= 0.18 || drillingNow > 0);
      return holdStill(drillOn);
    }
    return holdStill(false);
  }

  if (mem.siteGoal &&
      ((carried > mem.siteGoal.carry0 + 0.1) ||
       (delivered > mem.siteGoal.delivered0 + 0.000001) ||
       (mem.siteGoal.phase === "drill" &&
        drillingNow >= 5.8 &&
        !siteObs &&
        now - mem.siteGoal.started > 5.5))) {
    finishSample();
  }

  if (mem.siteGoal && siteObs) {
    var siteA = (mem.ph + siteObs.bearing) * Math.PI / 180;
    mem.siteGoal.x =
      mem.px + Math.max(0, siteObs.distance) * Math.cos(siteA);
    mem.siteGoal.y =
      mem.py + Math.max(0, siteObs.distance) * Math.sin(siteA);
    if (finite(siteObs.value)) mem.siteGoal.value = siteObs.value;
    mem.siteGoal.lastSeen = now;
  }

  var bumpedNow = !!obs.bumped;
  if (bumpedNow && (!mem.prevBumped || now >= mem.bumpUntil)) {
    var openLeft = Math.max(
      mem.rayValues[5], mem.rayValues[6],
      mem.rayValues[7], mem.rayValues[8]
    );
    var openRight = Math.max(
      mem.rayValues[0], mem.rayValues[1],
      mem.rayValues[2], mem.rayValues[3]
    );
    mem.bumpSign = openLeft >= openRight ? 1 : -1;
    mem.bumpUntil = now + 0.9;
  }
  mem.prevBumped = bumpedNow;

  function dockPosition() {
    if (obs.docked) return true;
    if (obs.beacon &&
        finite(obs.beacon.distance) &&
        obs.beacon.distance <= 0.85) return true;
    return baseGlobalDistance() <= 0.85;
  }
  function deliveryRange() {
    if (obs.docked) return true;
    if (obs.beacon &&
        finite(obs.beacon.distance) &&
        obs.beacon.distance <= 2.8) return true;
    return baseGlobalDistance() <= 2.8;
  }

  function handleDock() {
    if (!obs.docked && baseDistance() > 0.75) {
      mem.state = "return";
      return driveToBase();
    }
    if (carried > 0) return holdStill(false);

    if (siteObs && canSampleAt(siteObs.distance)) {
      if (beginSite(siteObs)) {
        mem.state = "explore";
        return siteAction();
      }
    }

    var attempts = 0;
    while (attempts < 4) {
      if (!mem.job) selectNextJob();
      if (!mem.job) break;
      var jp = jobPlan(mem.job);
      if (jp && jp.need > 0.99 && battery > 0.94) {
        discardJob();
        attempts++;
        continue;
      }
      break;
    }

    if (!mem.job) return holdStill(false);
    var plan = jobPlan(mem.job);
    if (!plan || timeLeft < plan.seconds + 12) {
      return holdStill(false);
    }
    if (battery >= plan.need + 0.035) {
      mem.state = "explore";
      return null;
    }
    return holdStill(false);
  }

  if (mem.state === "return") {
    if (dockPosition()) {
      mem.state = "dock";
    } else {
      return driveToBase();
    }
  }

  if (mem.state === "dock") {
    var dockAction = handleDock();
    if (dockAction) return dockAction;
  }

  if (mem.state === "explore" &&
      obs.docked &&
      (carried > 0 || battery < 0.35)) {
    mem.state = "dock";
    var initialDockAction = handleDock();
    if (initialDockAction) return initialDockAction;
  }

  if (mem.state !== "explore") {
    if (mem.state === "return") return driveToBase();
    return holdStill(false);
  }

  var dBase = baseDistance();
  var retT = returnTime(dBase);
  var currentReturnNeed = returnNeed(carried);
  var mustReturn =
    carried >= mem.capacity ||
    timeLeft < retT + 14 ||
    battery < currentReturnNeed + 0.04;

  if (mem.siteGoal) {
    var activeSiteDistance = siteDistanceAndBearing().distance;
    if (!canSampleAt(activeSiteDistance)) mustReturn = true;
  }

  if (mustReturn) {
    mem.siteGoal = null;
    if (dockPosition()) {
      mem.state = "dock";
      var dockNow = handleDock();
      if (dockNow) return dockNow;
    } else {
      mem.state = "return";
      return driveToBase();
    }
  }

  if (mem.siteGoal) {
    var siteResult = siteAction();
    if (siteResult) return siteResult;
  }

  if (!mem.siteGoal && siteObs) {
    if (beginSite(siteObs)) {
      return siteAction();
    }
    mem.state = "return";
    if (dockPosition()) {
      mem.state = "dock";
      var dockForSite = handleDock();
      if (dockForSite) return dockForSite;
    }
    return driveToBase();
  }

  if (mem.job) advanceJob();
  if (!mem.job) selectNextJob();

  if (!mem.job) {
    if (baseGlobalDistance() < 2.5 || obs.docked) {
      mem.state = "dock";
      var idleDock = handleDock();
      if (idleDock) return idleDock;
    }
    mem.state = "return";
    return driveToBase();
  }

  var currentPlan = jobPlan(mem.job);
  if (!currentPlan ||
      timeLeft < currentPlan.seconds + 12 ||
      battery < currentPlan.need + 0.025) {
    if (baseGlobalDistance() < 2.8 || obs.docked) {
      mem.state = "dock";
      var waitDock = handleDock();
      if (waitDock) return waitDock;
    }
    mem.state = "return";
    return driveToBase();
  }

  var target = jobTarget(mem.job);
  var navKey = jobKey(mem.job);
  var stopRadius = mem.job.phase === 0 ? 4.0 : 2.8;
  return drivePoint(
    target.x,
    target.y,
    stopRadius,
    1.35,
    navKey
  );
}

function act(obs, mem) {
  const D2R = Math.PI / 180;
  const R2D = 180 / Math.PI;
  const WB = 0.6;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = (a + Math.PI) % (2 * Math.PI);
    if (a < 0) a += 2 * Math.PI;
    return a - Math.PI;
  }
  function wrapDeg(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function dist(x1, y1, x2, y2) {
    let dx = x1 - x2, dy = y1 - y2;
    return Math.sqrt(dx * dx + dy * dy);
  }

  let t = (typeof obs.t === "number") ? obs.t : 0;
  let rawH = wrap(((obs.heading || 0)) * D2R);

  if (!mem.init) {
    mem.init = true;
    let m = obs.mission || {};
    let sz = m.size;
    let sx = 400, sy = 400;
    if (typeof sz === "number") {
      sx = sz; sy = sz;
    } else if (sz && typeof sz === "object") {
      sx = sz.x || sz.w || sz.width || 400;
      sy = sz.y || sz.h || sz.height || 400;
    }
    let mb = m.base || {};
    let bx = (typeof mb.x === "number") ? mb.x : obs.x;
    let by = (typeof mb.y === "number") ? mb.y : obs.y;
    let hintsRaw = m.hints || [];
    let allX = [bx], allY = [by];
    for (let i = 0; i < hintsRaw.length; i++) {
      let h = hintsRaw[i];
      if (h && typeof h.x === "number" && typeof h.y === "number") {
        allX.push(h.x); allY.push(h.y);
      }
    }
    let minC = Math.min.apply(null, allX);
    let maxC = Math.max.apply(null, allX);
    let minD = Math.min.apply(null, allY);
    let maxD = Math.max.apply(null, allY);
    let centered = (minC < -1 || maxC > Math.max(sx, sy) + 1 || minD < -1 || maxD > Math.max(sx, sy) + 1 ||
                    bx < -0.01 * sx || by < -0.01 * sy || bx > sx * 1.01 || by > sy * 1.01);
    if (centered) {
      mem.minX = -sx / 2; mem.maxX = sx / 2;
      mem.minY = -sy / 2; mem.maxY = sy / 2;
    } else {
      mem.minX = 0; mem.maxX = sx;
      mem.minY = 0; mem.maxY = sy;
    }
    mem.base = { x: bx, y: by };
    mem.capacity = m.capacity || 5;
    mem.missionSeconds = m.seconds || 1200;
    let initialLeft = (typeof obs.timeLeft === "number") ? obs.timeLeft : mem.missionSeconds;
    mem.endT = t + initialLeft;

    mem.hints = [];
    for (let i = 0; i < hintsRaw.length; i++) {
      let h = hintsRaw[i];
      if (!h) continue;
      let hx = +h.x;
      let hy = +h.y;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      let ve = (h.estimate != null ? h.estimate : (h.value != null ? h.value : 1));
      ve = +ve;
      if (!isFinite(ve) || ve <= 0) ve = 1;
      if (hx < mem.minX - 80 || hx > mem.maxX + 80 || hy < mem.minY - 80 || hy > mem.maxY + 80) continue;
      mem.hints.push({ x: hx, y: hy, est: ve, status: 0, attempts: 0, id: i });
    }
    let ests = [];
    for (let i = 0; i < mem.hints.length; i++) ests.push(mem.hints[i].est);
    ests.sort(function(a, b) { return a - b; });
    mem.medEst = ests.length ? ests[Math.floor(ests.length * 0.5)] : 1;
    mem.maxEst = ests.length ? ests[ests.length - 1] : 1;

    mem.px = obs.x;
    mem.py = obs.y;
    mem.h = rawH;
    mem.cBias = 0;
    mem.compassBadUntil = -1;
    mem.lastRawH = rawH;
    mem.lastGpsX = obs.x;
    mem.lastGpsY = obs.y;
    mem.lastGpsT = t;
    mem.gpsFrozenTime = 0;
    mem.lastBattery = (typeof obs.battery === "number") ? obs.battery : 1;
    mem.lastCarried = obs.carried || 0;
    mem.lastCarriedValue = obs.carriedValue || 0;
    mem.lastDelivered = obs.delivered || 0;

    mem.cmdL = 0; mem.cmdR = 0;
    mem.iL = 0; mem.iR = 0;
    mem.lastSteer = 0;
    mem.mode = "auto";
    mem.returning = false;
    mem.target = null;
    mem.search = null;
    mem.sampling = null;
    mem.siteData = null;
    mem.siteCooldownUntil = -1;
    mem.ignoredSites = [];
    mem.lastBump = -10;
    mem.escapeSign = 1;
    mem.escape = null;
    mem.stuckCount = 0;
    mem.stuckCheck = null;
    mem.ePerM = 0.0010;
    mem.eMax = 0;
    mem.eCount = 0;
    mem.moveSpeedEwma = 1.4;
    mem.distTraveled = 0;
    mem.cal = 0;
    mem.chargeStart = 0;
    mem.rng = 123456789;
    mem.rayAng = [-80, -60, -40, -20, 0, 20, 40, 60, 80].map(function(a) { return a * D2R; });

    mem.explore = [];
    let stepG = 60;
    for (let gx = mem.minX + 25; gx <= mem.maxX - 20; gx += stepG) {
      for (let gy = mem.minY + 25; gy <= mem.maxY - 20; gy += stepG) {
        if (dist(gx, gy, mem.base.x, mem.base.y) > 28) {
          mem.explore.push({ x: gx, y: gy, used: false });
        }
      }
    }
  }

  let timeLeft = (typeof obs.timeLeft === "number") ? obs.timeLeft : Math.max(0, mem.endT - t);
  let dt = t - (typeof mem.lastT === "number" ? mem.lastT : t);
  let dtc = (dt > 0) ? clamp(dt, 0.02, 0.25) : 0.1;

  let vLobs = +obs.wheelLeft;
  let vRobs = +obs.wheelRight;
  if (!isFinite(vLobs)) vLobs = 0;
  if (!isFinite(vRobs)) vRobs = 0;
  let vC = 0.5 * (vLobs + vRobs);
  let omegaMeas = (vRobs - vLobs) / WB;

  // Wheel odometry prediction.
  let hOld = mem.h;
  let hmid = hOld + omegaMeas * dtc * 0.5;
  mem.px += vC * Math.cos(hmid) * dtc;
  mem.py += vC * Math.sin(hmid) * dtc;
  mem.h = wrap(hOld + omegaMeas * dtc);

  let gdx = obs.x - mem.lastGpsX;
  let gdy = obs.y - mem.lastGpsY;
  let gd = Math.sqrt(gdx * gdx + gdy * gdy);
  let sameGps = Math.abs(gdx) < 1e-9 && Math.abs(gdy) < 1e-9;
  let wasFrozen = mem.gpsFrozenTime > 1.5;

  if (sameGps && Math.abs(vC) > 0.18) {
    mem.gpsFrozenTime += dtc;
  } else if (!sameGps) {
    mem.gpsFrozenTime = 0;
  } else {
    mem.gpsFrozenTime = Math.max(0, mem.gpsFrozenTime - dtc * 0.5);
  }
  let gpsFrozen = mem.gpsFrozenTime > 1.4;

  if (!sameGps) {
    if (wasFrozen) {
      if (gd < 80) { mem.px = obs.x; mem.py = obs.y; }
    } else if (gd < 5) {
      let a = gd > 1 ? 0.5 : 0.32;
      mem.px += (obs.x - mem.px) * a;
      mem.py += (obs.y - mem.py) * a;
    } else if (mem.gpsFrozenTime > 2) {
      mem.px = obs.x; mem.py = obs.y;
    }
  } else if (!gpsFrozen) {
    mem.px += (obs.x - mem.px) * 0.005;
    mem.py += (obs.y - mem.py) * 0.005;
  }

  // Detect obviously bad compass jumps/sticks.
  let dRaw = wrap(rawH - mem.lastRawH);
  let expectedYaw = omegaMeas * dtc;
  if (Math.abs(wrap(dRaw - expectedYaw)) > 35 * D2R && Math.abs(expectedYaw) < 25 * D2R) {
    mem.compassBadUntil = t + 5;
  }
  if (Math.abs(dRaw) < 2 * D2R && Math.abs(expectedYaw) > 10 * D2R && Math.abs(omegaMeas) > 0.25) {
    mem.compassBadUntil = t + 3;
  }

  // Use GPS course to calibrate/repair heading.
  if (!gpsFrozen && gd > 0.035 && Math.abs(vC) > 0.25) {
    let course = Math.atan2(gdy, gdx);
    if (vC < 0) course = wrap(course + Math.PI);
    if (Math.abs(omegaMeas) < 0.75) {
      let corr = wrap(course - mem.h);
      if (Math.abs(corr) < 1.2) {
        mem.h = wrap(mem.h + corr * 0.14);
        if (t > mem.compassBadUntil) {
          let b = wrap(rawH - mem.h);
          let db = wrap(b - mem.cBias);
          if (Math.abs(db) < 1.1) mem.cBias = wrap(mem.cBias + db * 0.05);
        }
      }
    }
  }

  // Gentle compass correction when it is not known-bad.
  if (t > mem.compassBadUntil) {
    let hc = wrap(rawH - mem.cBias);
    let corr = wrap(hc - mem.h);
    if (Math.abs(corr) < 0.7) mem.h = wrap(mem.h + corr * 0.03);
  }

  let px = mem.px;
  let py = mem.py;

  let baseDistEst = dist(px, py, mem.base.x, mem.base.y);
  let beacon = obs.beacon;
  let beaconDist = (beacon && typeof beacon.distance === "number") ? beacon.distance : Infinity;
  let baseDist = Math.min(baseDistEst, beaconDist);
  let atBase = !!(obs.docked || (beaconDist < 3.0) || (baseDistEst < 2.8 && !gpsFrozen));

  // Energy and achieved-speed estimates.
  let batteryNow = (typeof obs.battery === "number") ? obs.battery : mem.lastBattery;
  let use = (mem.lastBattery - batteryNow) + Math.max(0, +obs.solar || 0) * dtc;
  let groundDist = (!gpsFrozen && gd < 5) ? gd : Math.abs(vC) * dtc;
  if (!mem.sampling && groundDist > 0.02 && Math.abs(vC) > 0.12 &&
      batteryNow < 0.995 && use > 1e-7) {
