        var eNeed0 = (bd0 + sd0 * 2) * Math.max(0.00015, mem.ePerM * 1.5) * (1 + 0.15 * carried) + 0.04;
        if (battery < eNeed0) safe = false;
      }
      if (safe) {
        mem.state = "sample";
        mem.sample = { startT: t, carriedBefore: carried, valueBefore: carriedValue, lastSite: null };
