        hint.status = 2; mem.target = null; mem.path = null;
        var cf = wheelCmd(0, 0);
        return { left: cf.left, right: cf.right, drill: false };
      }
      var pt = mem.searchPts[mem.searchIndex];
      var dd = dist(mem.px, mem.py, pt.x, pt.y);
      if (dd < 1.25) {
        mem.searchIndex++; mem.path = null;
        if (mem.searchIndex >= mem.searchPts.length) {
          hint.status = 2; mem.target = null;
          var cf2 = wheelCmd(0, 0);
          return { left: cf2.left, right: cf2.right, drill: false };
        }
        pt = mem.searchPts[mem.searchIndex];
      }
      return navigate(pt.x, pt.y, 1.3, 0.5, true);
    }
    mem.target = null;
    var cf3 = wheelCmd(0, 0);
    return { left: cf3.left, right: cf3.right, drill: false };
  }

  var fallback = wheelCmd(0, 0);
  return { left: fallback.left, right: fallback.right, drill: false };
}

function act(obs, mem) {
  const D2R = Math.PI / 180;
  const R2D = 180 / Math.PI;
  const WB = 0.6;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = (a + Math.PI) % (2 * Math.PI);
    if (a < 0) a += 2 * Math.PI;
    return a - Math.PI;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x1 - x2, dy = y1 - y2;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var t = (typeof obs.t === "number" && isFinite(obs.t)) ? obs.t : 0;

  if (!mem.init) {
    mem.init = true;
    var m = obs.mission || {};
    var sz = m.size;
    var sx = 400, sy = 400;
    if (typeof sz === "number" && isFinite(sz) && sz > 0) {
      sx = sy = sz;
    } else if (sz && typeof sz === "object") {
      sx = +sz.x || +sz.w || +sz.width || 400;
      sy = +sz.y || +sz.h || +sz.height || sx;
      if (!isFinite(sx) || sx <= 0) sx = 400;
      if (!isFinite(sy) || sy <= 0) sy = 400;
    }
    var mb = m.base || {};
    mem.base = {
      x: (typeof mb.x === "number" && isFinite(mb.x)) ? mb.x : (+obs.x || 0),
      y: (typeof mb.y === "number" && isFinite(mb.y)) ? mb.y : (+obs.y || 0)
    };
    mem.capacity = +m.capacity || 5;
    mem.missionSeconds = +m.seconds || 1200;
    var initialLeft = (typeof obs.timeLeft === "number" && isFinite(obs.timeLeft)) ? obs.timeLeft : mem.missionSeconds;
    mem.endT = t + initialLeft;

    var hintsRaw = (m.hints && m.hints.length) ? m.hints : [];
    var centered = false;
    function outsideBounds(x, y) {
      return x < -1 || x > sx + 1 || y < -1 || y > sy + 1;
    }
    if (outsideBounds(mem.base.x, mem.base.y)) centered = true;
    var i, hx, hy;
    for (i = 0; i < hintsRaw.length; i++) {
      var hh = hintsRaw[i];
      if (!hh) continue;
      hx = +hh.x; hy = +hh.y;
      if (isFinite(hx) && isFinite(hy) && outsideBounds(hx, hy)) {
        centered = true;
        break;
      }
    }
    if (centered) {
      mem.minX = -sx / 2; mem.maxX = sx / 2;
      mem.minY = -sy / 2; mem.maxY = sy / 2;
    } else {
      mem.minX = 0; mem.maxX = sx;
      mem.minY = 0; mem.maxY = sy;
    }
    if (!(mem.minX < mem.maxX)) { mem.minX = -200; mem.maxX = 200; }
    if (!(mem.minY < mem.maxY)) { mem.minY = -200; mem.maxY = 200; }

    mem.hints = [];
    for (i = 0; i < hintsRaw.length; i++) {
      var h = hintsRaw[i];
      if (!h) continue;
      hx = +h.x; hy = +h.y;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (hx < mem.minX - 50 || hx > mem.maxX + 50 || hy < mem.minY - 50 || hy > mem.maxY + 50) continue;
      var est = +h.estimate;
      if (!isFinite(est) || est <= 0) est = 1;
      mem.hints.push({ x: hx, y: hy, est: est, status: 0 });
    }
    var ests = [];
    for (i = 0; i < mem.hints.length; i++) ests.push(mem.hints[i].est);
    ests.sort(function(a, b) { return a - b; });
    mem.medEst = ests.length ? ests[Math.floor(ests.length / 2)] : 1;
    mem.maxEst = ests.length ? ests[ests.length - 1] : 1;

    mem.px = +obs.x || 0;
    mem.py = +obs.y || 0;
    mem.h = wrap((+obs.heading || 0) * D2R);
    mem.cbias = 0;
    mem.lastRawH = mem.h;
    mem.compassIgnoreUntil = -1;
    mem.lastGpsX = mem.px;
    mem.lastGpsY = mem.py;
    mem.gpsFrozenT = 0;

    mem.lastBattery = (typeof obs.battery === "number" && isFinite(obs.battery)) ? obs.battery : 1;
    mem.lastCarried = +obs.carried || 0;
    mem.lastCarriedValue = +obs.carriedValue || 0;
    mem.lastDelivered = +obs.delivered || 0;

    mem.intL = 0;
    mem.intR = 0;
    mem.lastSteer = 0;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.mode = "work";
    mem.task = null;
    mem.sample = null;
    mem.siteCooldownUntil = -1;
    mem.escapeUntil = -1;
    mem.escapeDir = 1;
    mem.lastBumped = (typeof obs.bumped === "number") ? obs.bumped : 0;
    mem.lastBumpedBool = !!obs.bumped;
    mem.bumpStreak = 0;
    mem.lastBumpT = -100;
    mem.stuckT = t;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
    mem.chargeStart = t;
    mem.ePM = 0.0007;
    mem.eCount = 0;
    mem.avgSpeed = 1.2;
    mem.explorePts = [];
    var step = Math.max(45, Math.min(85, (mem.maxX - mem.minX) / 6));
    for (var xx = mem.minX + step * 0.5; xx < mem.maxX; xx += step) {
      for (var yy = mem.minY + step * 0.5; yy < mem.maxY; yy += step) {
        if (dist(xx, yy, mem.base.x, mem.base.y) > 12) {
          mem.explorePts.push({ x: xx, y: yy, used: false });
        }
      }
    }
    mem.lastT = t - 0.1;
  }

  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.6) dt = 0.1;
  mem.dt = dt;
  mem.lastT = t;

  var wL = +obs.wheelLeft;
  var wR = +obs.wheelRight;
  if (!isFinite(wL)) wL = 0;
  if (!isFinite(wR)) wR = 0;
  var vAvg = 0.5 * (wL + wR);
  var omega = (wR - wL) / WB;
  var battery = +obs.battery;
  if (!isFinite(battery)) battery = mem.lastBattery;
  var carried = +obs.carried || 0;
  var carriedValue = +obs.carriedValue || 0;
  var delivered = +obs.delivered || 0;
  var timeLeft = (typeof obs.timeLeft === "number" && isFinite(obs.timeLeft)) ? obs.timeLeft : Math.max(0, mem.endT - t);
  var rawH = wrap((+obs.heading || 0) * D2R);
  var solar = Math.max(0, +obs.solar || 0);

  var oldH = mem.h;
  mem.px += vAvg * Math.cos(oldH + omega * dt * 0.5) * dt;
  mem.py += vAvg * Math.sin(oldH + omega * dt * 0.5) * dt;
  mem.h = wrap(oldH + omega * dt);

  var gx = +obs.x, gy = +obs.y;
  if (!isFinite(gx)) gx = mem.lastGpsX;
  if (!isFinite(gy)) gy = mem.lastGpsY;
  var gdx = gx - mem.lastGpsX;
  var gdy = gy - mem.lastGpsY;
  var gd = Math.sqrt(gdx * gdx + gdy * gdy);
  var sameGps = gd < 1e-7;
  var wasFrozen = mem.gpsFrozenT > 2.0;
  if (sameGps) {
    if (Math.abs(vAvg) > 0.12) mem.gpsFrozenT += dt;
    else mem.gpsFrozenT = Math.max(0, mem.gpsFrozenT - dt * 0.5);
  } else {
    var dPos = dist(gx, gy, mem.px, mem.py);
    var alpha = 0.35;
    if (dPos > 5) alpha = 0.12;
    if (wasFrozen || dPos > 40) alpha = 0.8;
    mem.px += (gx - mem.px) * alpha;
    mem.py += (gy - mem.py) * alpha;
    if (gd > 0.03 && gd < 4 && Math.abs(vAvg) > 0.15 && Math.abs(omega) < 0.6) {
      var course = Math.atan2(gdy, gdx);
      if (vAvg < 0) course = wrap(course + Math.PI);
      var diffH = wrap(course - mem.h);
      if (Math.abs(diffH) < 0.9) {
        mem.h = wrap(mem.h + diffH * 0.15);
        var desiredCb = wrap(rawH - course);
        var cbDiff = wrap(desiredCb - mem.cbias);
        if (Math.abs(cbDiff) < 1.0) mem.cbias = wrap(mem.cbias + cbDiff * 0.04);
      }
    }
    mem.lastGpsX = gx;
    mem.lastGpsY = gy;
    mem.gpsFrozenT = 0;
  }
  var gpsFrozen = mem.gpsFrozenT > 2.5;

  var dRaw = wrap(rawH - mem.lastRawH);
  var expectedYaw = omega * dt;
  if (Math.abs(wrap(dRaw - expectedYaw)) > 50 * D2R && Math.abs(expectedYaw) < 20 * D2R) {
    mem.compassIgnoreUntil = t + 2.0;
  }
  if (Math.abs(dRaw) < 1 * D2R && Math.abs(expectedYaw) > 10 * D2R && Math.abs(omega) > 0.2) {
    mem.compassIgnoreUntil = t + 1.5;
  }
  mem.lastRawH = rawH;
  if (t > mem.compassIgnoreUntil) {
    var compH = wrap(rawH - mem.cbias);
    var corrH = wrap(compH - mem.h);
    if (Math.abs(corrH) < 0.9) mem.h = wrap(mem.h + corrH * 0.12);
  }

  var prevBat = mem.lastBattery;
  var consumption = (prevBat - battery) + solar * dt;
  var drillingNow = !!obs.drilling || mem.mode === "sample";
  var moveDist = (!sameGps && gd < 5) ? gd : Math.abs(vAvg) * dt;
  if (moveDist > 0.01 && Math.abs(vAvg) > 0.1 && !drillingNow) {
    var pM = Math.max(0, consumption) / moveDist;
    var loadF = 1 + 0.12 * carried;
    var pBase = pM / loadF;
    if (pBase > 0.00003 && pBase < 0.03) {
      if (mem.eCount < 8) mem.ePM = pBase;
      else mem.ePM = mem.ePM * 0.98 + pBase * 0.02;
      mem.ePM = clamp(mem.ePM, 0.00025, 0.02);
      mem.eCount++;
    }
  }
  if (!sameGps && gd > 0.01 && dt > 0.01) {
    var spd = gd / dt;
    if (spd > 0.05 && spd < 5) mem.avgSpeed = mem.avgSpeed * 0.97 + spd * 0.03;
  } else if (Math.abs(vAvg) > 0.05) {
    mem.avgSpeed = mem.avgSpeed * 0.98 + Math.abs(vAvg) * 0.02;
  }
  mem.avgSpeed = clamp(mem.avgSpeed, 0.4, 3.0);

  function finish(cmd) {
    var l = +cmd.left;
    var r = +cmd.right;
    if (!isFinite(l)) l = 0;
    if (!isFinite(r)) r = 0;
    l = clamp(l, -1, 1);
    r = clamp(r, -1, 1);
    mem.lastLeft = l;
    mem.lastRight = r;
    mem.lastBattery = battery;
    mem.lastCarried = carried;
    mem.lastCarriedValue = carriedValue;
    mem.lastDelivered = delivered;
    mem.lastT = t;
    return { left: l, right: r, drill: !!cmd.drill };
  }

  function wheelCmd(tl, tr) {
    tl = clamp(tl, -2.8, 2.8);
    tr = clamp(tr, -2.8, 2.8);
    var wl = +obs.wheelLeft;
    var wr = +obs.wheelRight;
    if (!isFinite(wl)) wl = 0;
    if (!isFinite(wr)) wr = 0;
    var eL = tl - wl;
    var eR = tr - wr;
    var dtt = mem.dt || 0.1;

    mem.intL += eL * dtt * 0.85;
    mem.intR += eR * dtt * 0.85;
    mem.intL = clamp(mem.intL, -0.75, 0.75);
    mem.intR = clamp(mem.intR, -0.75, 0.75);

    var base = 1 / 3.0;
    var cmdL = base * tl + 0.9 * eL + mem.intL;
    var cmdR = base * tr + 0.9 * eR + mem.intR;

    if (Math.abs(tl) < 0.05 && Math.abs(tr) < 0.05) {
      var pitch = +obs.pitch || 0;
      var slopeFF = clamp(pitch / 50, -1, 1) * 0.10;
      cmdL += slopeFF;
      cmdR += slopeFF;
    }

    if ((cmdL > 1 && eL > 0) || (cmdL < -1 && eL < 0)) mem.intL -= eL * dtt * 0.85;
    if ((cmdR > 1 && eR > 0) || (cmdR < -1 && eR < 0)) mem.intR -= eR * dtt * 0.85;
    mem.intL = clamp(mem.intL, -0.8, 0.8);
    mem.intR = clamp(mem.intR, -0.8, 0.8);

    if (Math.abs(tl) < 0.03 && Math.abs(wl) < 0.05) mem.intL *= Math.max(0, 1 - 0.2 * dtt);
    if (Math.abs(tr) < 0.03 && Math.abs(wr) < 0.05) mem.intR *= Math.max(0, 1 - 0.2 * dtt);

    return { left: clamp(cmdL, -1, 1), right: clamp(cmdR, -1, 1) };
