      if (d >= 14.8) continue;
      var a = (i - 4) * 20 * D2R;
      var diff = wrap(c - a);
      var along = d * Math.cos(diff);
      if (along <= 0.01) continue;
      var lat = Math.abs(d * Math.sin(diff));
      var margin = 0.55 + 0.06 * Math.min(along, 5.0);
      if (lat < margin || Math.abs(diff) < 0.10) {
        var cl = along - 0.55;
        if (cl < minClear) minClear = cl;
      }
    }

    var ga = mem.h + c;
    var dx = Math.cos(ga);
    var dy = Math.sin(ga);
    var edge = 1e9;
    var bx = mem.px;
    var by = mem.py;
    if (dx > 1e-6) edge = Math.min(edge, (mem.maxX - 0.9 - bx) / dx);
    else if (dx < -1e-6) edge = Math.min(edge, (mem.minX + 0.9 - bx) / dx);
    if (dy > 1e-6) edge = Math.min(edge, (mem.maxY - 0.9 - by) / dy);
    else if (dy < -1e-6) edge = Math.min(edge, (mem.minY + 0.9 - by) / dy);
    if (edge < minClear) minClear = edge - 0.4;
    return Math.max(0, minClear);
  }

  function chooseSteer(relGoal, vmax) {
    relGoal = wrap(relGoal);
    var bestC = relGoal;
    var bestClear = rayClear(relGoal);
    var bestScore = -1e18;
    var need = 0.72 + 0.35 * Math.min(vmax, 2.2);
    for (var q = -16; q <= 16; q++) {
      var c = q * 10 * D2R;
      if (Math.abs(c) > 1.45) continue;
      var clear = rayClear(c);
      var err = Math.abs(wrap(c - relGoal));
      var score = -err * 2.2 + Math.min(clear, 4.0) * 1.4;
      if (clear < need) score -= (need - clear) * 60;
      if (clear < 0.50) score -= 200;
      if (Math.abs(c - mem.lastSteer) > 0.7) score -= 0.15;
      if (Math.abs(c) < 0.02) score += 0.05;
      if (score > bestScore) {
        bestScore = score;
        bestC = c;
        bestClear = clear;
      }
    }
    if (Math.abs(relGoal) <= 1.45) {
      var c0 = relGoal;
      var clear0 = rayClear(c0);
      var score0 = Math.min(clear0, 4.0) * 1.4;
      if (clear0 < need) score0 -= (need - clear0) * 60;
      if (clear0 < 0.50) score0 -= 200;
      if (score0 > bestScore) {
        bestScore = score0;
        bestC = c0;
        bestClear = clear0;
      }
    }
    mem.lastSteer = bestC;
    return { c: bestC, clear: bestClear };
  }

  function move(relGoal, distGoal, stopDist, vmax) {
    relGoal = wrap(relGoal);
    if (!(distGoal > stopDist)) {
      var cStop = wheelCmd(0, 0);
      return { left: cStop.left, right: cStop.right, drill: false };
    }

    var v = Math.min(vmax, Math.max(0.05, (distGoal - stopDist) * 1.1 + 0.05));
    if (Math.abs(relGoal) > 1.85) {
      var turn = relGoal > 0 ? 1 : -1;
      var om = 1.7 * turn;
      var tl = -om * WB / 2;
      var tr = om * WB / 2;
      var cs = wheelCmd(tl, tr);
      mem.lastSteer = relGoal;
      return { left: cs.left, right: cs.right, drill: false };
    }

    var res = chooseSteer(relGoal, v);
    var c = res.c;
    var clear = res.clear;
    v *= Math.max(0.18, Math.cos(clamp(Math.abs(c), 0, 1.45)));
    var safe = (clear - 0.55) * 0.8;
    if (v > safe) v = safe;
    if (clear < 0.60) v = 0;

    var om2;
    if (v > 0.06) om2 = clamp(c * 2.2, -1.9, 1.9);
    else om2 = clamp(c * 2.0, -2.0, 2.0);

    var targetL = v - om2 * WB / 2;
    var targetR = v + om2 * WB / 2;
    targetL = clamp(targetL, -2.8, 2.8);
    targetR = clamp(targetR, -2.8, 2.8);
    var cmd = wheelCmd(targetL, targetR);
    return { left: cmd.left, right: cmd.right, drill: false };
  }

  function baseDistance() {
    var d = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    if (obs.beacon && isFinite(+obs.beacon.distance)) {
      d = Math.min(d, +obs.beacon.distance);
    }
    return d;
  }

  function needReturn() {
    var db = baseDistance();
    if (carried >= mem.capacity) return true;
    if (carried > 0.01) {
      var tRet = db / Math.max(0.45, mem.avgSpeed * 0.7) + 12;
      if (timeLeft < tRet + 12) return true;
    }
    var e = Math.max(0.00035, mem.ePM * 1.45);
    var reserve = db * e * (1 + 0.12 * carried) + 0.05 + 0.008 * carried;
    if (battery < reserve && db > 3.0) return true;
    if (battery < 0.07) return true;
    if (carried > 0.01 && timeLeft < 25 && db < 60) return true;
    return false;
  }

  function pickHint() {
    var best = -1;
    var bestScore = -1e18;
    var avg = Math.max(0.5, mem.avgSpeed * 0.65);
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 0) continue;
      var d = dist(mem.px, mem.py, h.x, h.y);
      var db = dist(h.x, h.y, mem.base.x, mem.base.y);
      var tNeed = (d + 65 + db * 1.05) / avg + 18;
      if (timeLeft < tNeed - 10) continue;
      if (carried > 0.01 && timeLeft < tNeed + 8) continue;
      var e = Math.max(0.00028, mem.ePM * 1.45);
      var needB = (d + 50 + db) * e * (1 + 0.12 * carried) + 0.05;
      if (needB > battery + 0.02) continue;
      var score = h.est / Math.pow(d + 0.55 * db + 18, 0.72);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function pickExplore() {
    var best = null;
    var bestD = 1e18;
    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.used) continue;
      var d = dist(mem.px, mem.py, p.x, p.y);
      if (d > 4 && d < bestD) {
        bestD = d;
        best = p;
      }
    }
    if (best) {
      best.used = true;
      return { x: best.x, y: best.y };
    }
    for (var j = 0; j < mem.explorePts.length; j++) mem.explorePts[j].used = false;
    if (mem.explorePts.length) {
      var q = mem.explorePts[(Math.floor(t * 0.1) + 1) % mem.explorePts.length];
      q.used = true;
      return { x: q.x, y: q.y };
    }
    var cx = (mem.minX + mem.maxX) / 2;
    var cy = (mem.minY + mem.maxY) / 2;
    var rx = (mem.maxX - mem.minX) * 0.35;
    var ry = (mem.maxY - mem.minY) * 0.35;
    var ang = t * 0.7;
    return { x: cx + Math.cos(ang) * rx, y: cy + Math.sin(ang) * ry };
