    var uR = kp * eR + mem.iR + ff;

    if (uL > 1 && eL > 0) {
      mem.iL -= ki * eL * dt;
      uL = kp * eL + mem.iL + ff;
    }
    if (uL < -1 && eL < 0) {
      mem.iL -= ki * eL * dt;
      uL = kp * eL + mem.iL + ff;
    }
    if (uR > 1 && eR > 0) {
      mem.iR -= ki * eR * dt;
      uR = kp * eR + mem.iR + ff;
    }
    if (uR < -1 && eR < 0) {
      mem.iR -= ki * eR * dt;
      uR = kp * eR + mem.iR + ff;
    }

    var brakeLimit = 0.68;
    if (Math.abs(wL) > brakeLimit) {
      uL = -Math.sign(wL) * Math.min(1, 0.35 + (Math.abs(wL) - brakeLimit) * 4.0);
    }
    if (Math.abs(wR) > brakeLimit) {
      uR = -Math.sign(wR) * Math.min(1, 0.35 + (Math.abs(wR) - brakeLimit) * 4.0);
    }
    if (Math.abs(vAvg) > 0.85) {
      var bb = -Math.sign(vAvg);
      uL = bb;
      uR = bb;
    }
    if (tL > 0 && wL > 0.55) uL = Math.min(uL, 0);
    if (tR > 0 && wR > 0.55) uR = Math.min(uR, 0);
    if (tL < 0 && wL < -0.55) uL = Math.max(uL, 0);
    if (tR < 0 && wR < -0.55) uR = Math.max(uR, 0);

    if (Math.abs(tL) < 0.02 && Math.abs(wL) < 0.03) mem.iL *= (1 - 0.12 * dt);
    if (Math.abs(tR) < 0.02 && Math.abs(wR) < 0.03) mem.iR *= (1 - 0.12 * dt);

    uL = clamp(uL, -1, 1);
    uR = clamp(uR, -1, 1);
    mem.lastCmdL = uL;
    mem.lastCmdR = uR;
    return { left: uL, right: uR, drill: false };
  }

  function drive(rel, d, vmax, stopDist) {
    rel = wrap(rel);
    if (!(d > stopDist)) return wheelCtrl(0, 0, true);

    var vmaxSafe = Math.min(vmax, 0.48);

    if (Math.abs(rel) > 1.0) {
      if (minRay() < 0.45) return wheelCtrl(-0.15, -0.15, false);
      var turnDir = rel > 0 ? 1 : -1;
      var turnSp = Math.min(0.34, Math.max(0.12, Math.abs(rel) * 0.25));
      return wheelCtrl(-turnDir * turnSp, turnDir * turnSp, false);
    }

    var res = chooseHeading(rel, vmaxSafe);
    var c = res.c;
    var cl = res.clear;

    if (cl < 0.72) {
      if (Math.abs(c) > 0.08) {
        var dir = c >= 0 ? 1 : -1;
        return wheelCtrl(-dir * 0.17, dir * 0.17, false);
      }
      return wheelCtrl(0, 0, true);
    }

    var v = Math.min(vmaxSafe, (d - stopDist) * 0.9 + 0.05);
    v = Math.min(v, 0.45);
    if (cl < 1.6) v *= Math.max(0.05, (cl - 0.72) / 0.88);
    if (Math.abs(pitch) > 12) v *= 1 / (1 + (Math.abs(pitch) - 12) / 30);
    if (carried > 0) v *= 1 / (1 + 0.03 * carried);
    v = Math.max(0, v);

    if (v < 0.04) {
      if (Math.abs(c) > 0.08) {
        var d2 = c >= 0 ? 1 : -1;
        return wheelCtrl(-d2 * 0.15, d2 * 0.15, false);
      }
      return wheelCtrl(0, 0, true);
    }

    var om = clamp(c * 1.6, -1.0, 1.0);
    var tl = v - om * WB * 0.5;
    var tr = v + om * WB * 0.5;
    var mm = Math.max(Math.abs(tl), Math.abs(tr));
    if (mm > 0.55) {
      tl *= 0.55 / mm;
      tr *= 0.55 / mm;
    }
    return wheelCtrl(tl, tr, false);
  }

  function driveToWorld(tx, ty, vmax, stopDist) {
    var d = dist(mem.px, mem.py, tx, ty);
    var rel = wrap(Math.atan2(ty - mem.py, tx - mem.px) - mem.h);
    return drive(rel, d, vmax, stopDist);
  }

  function goBase(vmax) {
    var bd = baseDistance();
    if (bd < 0.60) return wheelCtrl(0, 0, true);
    if (beacon && finite(+beacon.distance) && +beacon.distance < 20) {
      var rel = (finite(+beacon.bearing) ? +beacon.bearing : 0) * D2R;
      return drive(rel, bd, vmax, 0.55);
    }
    return driveToWorld(mem.base.x, mem.base.y, vmax, 0.55);
  }

  function markSampledHint(hi) {
    if (hi >= 0 && mem.hints[hi]) mem.hints[hi].status = 1;
    var bi = -1;
    var bd = 30;
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 0) continue;
      var d = dist(mem.px, mem.py, h.x, h.y);
      if (d < bd) {
        bd = d;
        bi = i;
      }
    }
    if (bi >= 0) mem.hints[bi].status = 1;
  }

  function isBadSite(x, y) {
    for (var i = 0; i < mem.badSites.length; i++) {
      var b = mem.badSites[i];
      if (t < b.until && dist(x, y, b.x, b.y) < 6.0) return true;
    }
    return false;
  }

  function canStartSample(sd) {
    var bd = baseDistance();
    var sp = Math.max(0.20, Math.min(0.50, mem.avgSpeed * 0.80));
    var retT = bd / sp + 10;
    var extra = sd / 0.28 + 14;
    if (timeLeft < retT + extra + 8) return false;
    var ePM = Math.max(0.0005, mem.ePM);
    var eNeed = (bd + sd + 20) * ePM * (1 + 0.15 * (carried + 1)) + 0.035 + 0.008 * carried;
    if (battery < eNeed + 0.02) return false;
    if (battery < 0.06) return false;
    return true;
  }

  function startSample(sn, sd) {
    var br = (finite(+sn.bearing) ? +sn.bearing : 0) * D2R;
    var sxSite = mem.px + sd * Math.cos(mem.h + br);
    var sySite = mem.py + sd * Math.sin(mem.h + br);
    var hi = -1;
    if (mem.target && mem.target.type === "hint") hi = mem.target.idx;
    mem.sample = {
      startT: t,
      carriedBefore: carried,
      lastSeen: t,
      siteX: sxSite,
      siteY: sySite,
      hintIdx: hi,
      ready: 0,
      drillStarted: false
    };
    mem.mode = "sample";
  }

  function abortSample() {
    if (mem.sample) {
      mem.badSites.push({ x: mem.sample.siteX, y: mem.sample.siteY, until: t + 80 });
      if (mem.badSites.length > 40) mem.badSites.shift();
      if (mem.sample.hintIdx >= 0 && mem.hints[mem.sample.hintIdx]) {
        mem.hints[mem.sample.hintIdx].status = 2;
      }
    }
    mem.sample = null;
    mem.mode = "work";
    mem.siteCooldownUntil = t + 4.0;
    mem.target = null;
    mem.search = null;
  }

  function sampleControl() {
    var s = mem.sample;
    if (!s) {
      mem.mode = "work";
      return null;
    }
    var sn = obs.site;
    var sd = 999;
    var br = 0;
    var seen = false;
    if (sn && finite(+sn.distance)) {
      sd = +sn.distance;
      br = (finite(+sn.bearing) ? +sn.bearing : 0) * D2R;
      s.lastSeen = t;
      s.siteX = mem.px + sd * Math.cos(mem.h + br);
      s.siteY = mem.py + sd * Math.sin(mem.h + br);
      seen = true;
    } else {
      sd = dist(mem.px, mem.py, s.siteX, s.siteY);
      if (!finite(sd)) sd = 999;
    }

    if (carried > s.carriedBefore + 0.1) {
      markSampledHint(s.hintIdx);
      mem.sample = null;
      mem.mode = "return";
      mem.target = null;
      mem.search = null;
      mem.siteCooldownUntil = t + 1.0;
      return wheelCtrl(0, 0, true);
    }

    var hasDrill = drilling > 0.01 || s.drillStarted;
    if (battery < 0.06 || timeLeft < 18) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }
    if (!seen && !hasDrill && t - s.lastSeen > 3.0) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }
    if (t - s.startT > 38 && !hasDrill) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }
    if (t - s.startT > 65) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }

    if (sd > 1.35 && (seen || t - s.lastSeen < 2.0)) {
      var vmaxS = 0.34;
      if (sd < 2.2) vmaxS = 0.20;
      if (seen) {
        return drive(br, sd, vmaxS, 1.02);
      } else {
        var relS = wrap(Math.atan2(s.siteY - mem.py, s.siteX - mem.px) - mem.h);
        return drive(relS, sd, vmaxS, 1.02);
      }
    }

    var still = Math.abs(vAvg) < 0.12 && Math.abs(wL) < 0.14 && Math.abs(wR) < 0.14;
    if (still) s.ready += dt;
    else s.ready = 0;

    var hc = wheelCtrl(0, 0, true);
    var drillNow = false;
    if ((sd <= 1.48 || t - s.lastSeen < 1.5 || drilling > 0.01) &&
        s.ready > 0.22 && Math.abs(vAvg) < 0.15) {
      drillNow = true;
      s.drillStarted = true;
    }
    if (drilling > 0.01) s.drillStarted = true;
    return { left: hc.left, right: hc.right, drill: drillNow };
  }

  function makeSearchPoints(hx, hy) {
    var pts = [{ x: hx, y: hy }];
    var dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];
    var step = 7;
    var x = hx;
    var y = hy;
    var dirIdx = 0;
    for (var leg = 0; leg < 8; leg++) {
      var len = Math.floor(leg / 2) + 1;
      for (var s = 0; s < len; s++) {
        x += dirs[dirIdx][0] * step;
        y += dirs[dirIdx][1] * step;
        if (x >= mem.minX + 1.5 && x <= mem.maxX - 1.5 && y >= mem.minY + 1.5 && y <= mem.maxY - 1.5) {
          pts.push({ x: x, y: y });
        }
      }
      dirIdx = (dirIdx + 1) % 4;
    }
    return pts;
  }

  function pickExplore() {
    var best = -1;
    var bestD = 1e18;
    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.used) continue;
      var d = dist(mem.px, mem.py, p.x, p.y);
      if (d < 3.0) {
        p.used = true;
        continue;
      }
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    if (best < 0) {
      for (var j = 0; j < mem.explorePts.length; j++) mem.explorePts[j].used = false;
      bestD = 1e18;
      for (var k = 0; k < mem.explorePts.length; k++) {
        var p2 = mem.explorePts[k];
        var d2 = dist(mem.px, mem.py, p2.x, p2.y);
        if (d2 > 3.0 && d2 < bestD) {
          bestD = d2;
          best = k;
        }
      }
    }
    return best;
  }

  function chooseTarget() {
    var best = -1;
    var bestScore = -1e18;
    var sp = Math.max(0.20, Math.min(0.50, mem.avgSpeed * 0.85));
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 0) continue;
      if (h.x < mem.minX + 1 || h.x > mem.maxX - 1 || h.y < mem.minY + 1 || h.y > mem.maxY - 1) {
        h.status = 3;
        continue;
      }
      var d = dist(mem.px, mem.py, h.x, h.y);
      var db = dist(h.x, h.y, mem.base.x, mem.base.y);
      var tNeed = (d + db + 45) / sp + 50;
      if (timeLeft < tNeed + 20) continue;
      var ePM = Math.max(0.0005, mem.ePM);
      var eNeed = (d + db + 50) * ePM * (1 + 0.15 * (carried + 1)) + 0.06;
      if (battery < eNeed + 0.02) continue;
      var val = h.est > 0 ? h.est : 1;
      var score = val / Math.pow(d + 0.9 * db + 25, 0.85);
      score *= 1 / (1 + d / 200);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    if (best >= 0) {
      mem.target = { type: "hint", idx: best };
      mem.mode = "goto";
      mem.search = null;
      mem.bumpTarget = null;
      mem.bumpCount = 0;
      return true;
    }
    var ex = pickExplore();
    if (ex >= 0) {
      var p = mem.explorePts[ex];
      var d0 = dist(mem.px, mem.py, p.x, p.y);
      var db0 = dist(p.x, p.y, mem.base.x, mem.base.y);
      var sp2 = Math.max(0.20, Math.min(0.50, mem.avgSpeed * 0.85));
      if (timeLeft > (d0 + db0 + 20) / sp2 + 30) {
        mem.target = { type: "explore", idx: ex, x: p.x, y: p.y };
        mem.mode = "goto";
        mem.search = null;
        return true;
      }
    }
    return false;
  }

  function finish(cmd) {
    var l = finite(+cmd.left) ? +cmd.left : 0;
    var r = finite(+cmd.right) ? +cmd.right : 0;
    l = clamp(l, -1, 1);
    r = clamp(r, -1, 1);
    mem.lastCmdL = l;
    mem.lastCmdR = r;
    mem.lastBattery = battery;
    mem.prevCarried = carried;
    mem.prevDelivered = delivered;
    return { left: l, right: r, drill: !!cmd.drill };
  }

  var carriedDelta = carried - mem.prevCarried;
  if (carriedDelta > 0.1) {
    var hiGain = mem.sample ? mem.sample.hintIdx : -1;
    markSampledHint(hiGain);
    mem.sample = null;
    mem.mode = "return";
    mem.target = null;
    mem.search = null;
    mem.siteCooldownUntil = t + 1.0;
  }
  if (carried < mem.prevCarried - 0.1 || delivered > mem.prevDelivered + 0.1) {
    mem.mode = "work";
    mem.target = null;
    mem.search = null;
    mem.chargeStart = t;
    mem.sample = null;
  }

  var bumpNow = false;
  if (typeof obs.bumped === "number") {
    var bv = +obs.bumped;
    if (bv > mem.lastBumpVal + 0.5) bumpNow = true;
    if (bv > mem.lastBumpVal) mem.lastBumpVal = bv;
  } else {
    if (obs.bumped && !mem.lastBumpBool) bumpNow = true;
    mem.lastBumpBool = !!obs.bumped;
  }
  if (bumpNow) {
    if (t - mem.lastBumpT < 5) mem.bumpStreak += 1;
    else mem.bumpStreak = 1;
    mem.lastBumpT = t;
    mem.escapeUntil = t + 1.3;
    var leftMin = 15;
    var rightMin = 15;
    for (var bi = 0; bi < 4; bi++) {
      var bdRay = finite(+rays[bi]) ? +rays[bi] : 15;
      if (bdRay < leftMin) leftMin = bdRay;
    }
    for (var bj = 5; bj < 9; bj++) {
      var bdRay2 = finite(+rays[bj]) ? +rays[bj] : 15;
      if (bdRay2 < rightMin) rightMin = bdRay2;
    }
    mem.escapeDir = leftMin > rightMin ? 1 : -1;
    if (mem.sample) {
      mem.sample = null;
      mem.mode = "work";
      mem.siteCooldownUntil = t + 2.0;
    }
    if (mem.target && mem.target.type === "hint") {
      if (mem.bumpTarget === mem.target.idx) mem.bumpCount += 1;
      else {
        mem.bumpTarget = mem.target.idx;
        mem.bumpCount = 1;
      }
      if (mem.bumpCount >= 3) {
        if (mem.hints[mem.target.idx]) mem.hints[mem.target.idx].status = 2;
        mem.target = null;
        mem.search = null;
        mem.mode = "work";
      }
    } else {
      mem.bumpTarget = null;
      mem.bumpCount = 0;
    }
    mem.stuckT = t;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
  }

  if (t - mem.stuckT > 2.5 && !mem.sample && !docked) {
    var smoved = dist(mem.px, mem.py, mem.stuckX, mem.stuckY);
    var cmdMag = Math.max(Math.abs(mem.lastCmdL || 0), Math.abs(mem.lastCmdR || 0));
    if (cmdMag > 0.25 && smoved < 0.15 && Math.abs(vAvg) > 0.08 && mem.gpsFrozenT < 5) {
      mem.escapeUntil = t + 1.0;
      mem.escapeDir = -mem.escapeDir;
      mem.stuckCount += 1;
      if (mem.stuckCount >= 3) {
        if (mem.target && mem.target.type === "hint" && mem.hints[mem.target.idx]) {
          mem.hints[mem.target.idx].status = 2;
        }
        mem.target = null;
        mem.search = null;
        mem.mode = "work";
        mem.stuckCount = 0;
      }
    }
    mem.stuckT = t;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
  }

  if (t < mem.escapeUntil) {
    var dirE = mem.escapeDir || 1;
    var back = -0.22;
    var diffE = 0.25 * dirE;
    return finish(wheelCtrl(back - diffE, back + diffE, false));
  }

  if (mem.mode === "sample" && mem.sample) {
    var outS = sampleControl();
    if (outS) return finish(outS);
  }

  if (!mem.sample && carried < mem.capacity - 0.01 && obs.site && mem.mode !== "return" && t > mem.siteCooldownUntil) {
    var sd0 = finite(+obs.site.distance) ? +obs.site.distance : 99;
    var sv0 = finite(+obs.site.value) ? +obs.site.value : 0;
    if (sd0 <= 8.0 && sv0 > 0) {
      var br0 = (finite(+obs.site.bearing) ? +obs.site.bearing : 0) * D2R;
      var sx0 = mem.px + sd0 * Math.cos(mem.h + br0);
      var sy0 = mem.py + sd0 * Math.sin(mem.h + br0);
      if (!isBadSite(sx0, sy0) && canStartSample(sd0)) {
        startSample(obs.site, sd0);
        var outS2 = sampleControl();
        if (outS2) return finish(outS2);
      }
    }
  }

  if (carried > 0.01) {
    var bdC = baseDistance();
    if (obs.docked || bdC <= 2.60) return finish(wheelCtrl(0, 0, true));
    return finish(goBase(0.45));
  }

  if (mem.mode === "return") {
    var bdR = baseDistance();
    if (bdR > 3.0) return finish(goBase(0.42));
    mem.mode = "work";
  }

  var bdNow = baseDistance();
  var atBase = docked || bdNow <= 2.8;

  if (atBase) {
    mem.mode = "work";
    if (battery < 0.60 && timeLeft > 100) {
      if (mem.chargeStart === null || mem.chargeStart === undefined) mem.chargeStart = t;
      if (t - mem.chargeStart < 25 && battery < 0.85 && timeLeft > 60) {
        return finish(wheelCtrl(0, 0, true));
      } else {
        mem.chargeStart = null;
      }
    } else {
      mem.chargeStart = null;
    }
  } else if (battery < 0.16 && timeLeft > 45) {
    mem.mode = "return";
    return finish(goBase(0.42));
  }

  if (!mem.target) {
    if (!chooseTarget()) {
      if (!atBase) return finish(goBase(0.40));
      return finish(wheelCtrl(0, 0, true));
    }
  }

  if (mem.target && mem.target.type === "hint") {
    var hi = mem.target.idx;
    var h = mem.hints[hi];
    if (!h || h.status !== 0) {
      mem.target = null;
      mem.search = null;
      mem.mode = "work";
      return finish(wheelCtrl(0, 0, true));
    }

    if (mem.search && mem.search.hintIdx === hi) {
      var sp = mem.search;
      if (t - sp.startT > 90 || sp.idx >= sp.pts.length) {
        h.status = 2;
        mem.search = null;
        mem.target = null;
        mem.mode = "work";
        return finish(wheelCtrl(0, 0, true));
      }
      var p = sp.pts[sp.idx];
      var dp = dist(mem.px, mem.py, p.x, p.y);
      if (dp < 1.0) {
        sp.idx += 1;
        sp.wpStart = t;
        if (sp.idx >= sp.pts.length) {
          h.status = 2;
          mem.search = null;
          mem.target = null;
          mem.mode = "work";
          return finish(wheelCtrl(0, 0, true));
        }
        p = sp.pts[sp.idx];
        dp = dist(mem.px, mem.py, p.x, p.y);
      }
      if (t - (sp.wpStart || t) > 18) {
        sp.idx += 1;
        sp.wpStart = t;
        if (sp.idx >= sp.pts.length) {
          h.status = 2;
          mem.search = null;
          mem.target = null;
          mem.mode = "work";
          return finish(wheelCtrl(0, 0, true));
        }
        p = sp.pts[sp.idx];
      }
      return finish(driveToWorld(p.x, p.y, 0.38, 0.80));
    }

    var dh = dist(mem.px, mem.py, h.x, h.y);
    if (dh < 4.5) {
      mem.mode = "search";
      mem.search = {
        hintIdx: hi,
        startT: t,
        pts: makeSearchPoints(h.x, h.y),
        idx: 0,
        wpStart: t
      };
      return finish(wheelCtrl(0, 0, true));
    }
    return finish(driveToWorld(h.x, h.y, 0.42, 1.0));
  }

  if (mem.target && mem.target.type === "explore") {
    var ei = mem.target.idx;
    var ep = mem.explorePts[ei];
    if (!ep || ep.used) {
      mem.target = null;
      mem.mode = "work";
      return finish(wheelCtrl(0, 0, true));
    }
    var de = dist(mem.px, mem.py, ep.x, ep.y);
    if (de < 3.0) {
      ep.used = true;
      mem.target = null;
      mem.mode = "work";
      return finish(wheelCtrl(0, 0, true));
    }
    return finish(driveToWorld(ep.x, ep.y, 0.40, 1.0));
  }

  return finish(wheelCtrl(0, 0, true));
}

function act(obs, mem) {
  var D2R = Math.PI / 180;
  var R2D = 180 / Math.PI;
  var WB = 0.6;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = (a + Math.PI) % (2 * Math.PI);
    if (a < 0) a += 2 * Math.PI;
    return a - Math.PI;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x1 - x2, dy = y1 - y2;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function finite(v) { return typeof v === "number" && isFinite(v); }

  var t = finite(+obs.t) ? +obs.t : 0;
  var battery = clamp(finite(+obs.battery) ? +obs.battery : 1, 0, 2);
  var carried = finite(+obs.carried) ? +obs.carried : 0;
  var carriedValue = finite(+obs.carriedValue) ? +obs.carriedValue : 0;
