        }
      }
    }
    if (!found) return null;

    var pts = [];
    var cur = goal;
    var guard = 0;
    while (cur !== -1 && guard++ < N) {
      var ix = cur % W;
      var iy = (cur - ix) / W;
      pts.push({ x: mem.minX + (ix + 0.5) * cs, y: mem.minY + (iy + 0.5) * cs });
      if (cur === start) break;
      cur = came[cur];
    }
    pts.reverse();
    if (pts.length) {
      var last = pts[pts.length - 1];
      if (dist(last.x, last.y, cgx, cgy) < 3.0) {
        pts[pts.length - 1] = { x: cgx, y: cgy };
      } else {
        pts.push({ x: cgx, y: cgy });
      }
    }
    return pts;
  }

  function navigate(tx, ty, vmax, stopDist) {
    var dFinal = dist(mem.px, mem.py, tx, ty);
    if (dFinal <= stopDist) return wheelCtrl(0, 0, true);

    var needPlan = !mem.path || mem.path.length === 0 ||
      Math.abs(mem.pathTx - tx) > 0.65 || Math.abs(mem.pathTy - ty) > 0.65 ||
      t > mem.nextPlanT;
    if (needPlan && dFinal > 2.0) {
      var p = planPath(tx, ty);
      if (p && p.length) {
        mem.path = p;
        mem.pathIndex = 0;
        mem.pathTx = tx;
        mem.pathTy = ty;
        mem.nextPlanT = t + 2.2;
      } else {
        mem.path = null;
        mem.pathTx = tx;
        mem.pathTy = ty;
        mem.nextPlanT = t + 1.2;
      }
    }

    var aimX = tx;
    var aimY = ty;
    if (mem.path && mem.path.length && t <= mem.nextPlanT + 1.0) {
      var guard = 0;
      while (mem.pathIndex < mem.path.length - 1 &&
             dist(mem.px, mem.py, mem.path[mem.pathIndex].x, mem.path[mem.pathIndex].y) < 0.85 &&
             guard++ < 24) {
        mem.pathIndex++;
      }
      var li = Math.min(mem.path.length - 1, mem.pathIndex + 2);
      if (dFinal < 4.0 || li >= mem.path.length - 1) {
        aimX = tx;
        aimY = ty;
      } else {
        aimX = mem.path[li].x;
        aimY = mem.path[li].y;
      }
    }
    var rel = wrap(Math.atan2(aimY - mem.py, aimX - mem.px) - mem.h);
    return driveRelative(rel, dFinal, vmax, stopDist);
  }

  function baseDistance() {
    var d = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    if (beacon && finite(+beacon.distance)) {
      var bd0 = +beacon.distance;
      if (bd0 >= 0 && bd0 < 24) d = Math.min(d, bd0);
    }
    return d;
  }

  function goBase(vmax) {
    var bd = baseDistance();
    if (bd < 0.55) return wheelCtrl(0, 0, true);
    if (beacon && finite(+beacon.distance) && +beacon.distance < 21) {
      var rel = (finite(+beacon.bearing) ? +beacon.bearing : 0) * D2R;
      return driveRelative(rel, bd, vmax, 0.55);
    }
    return navigate(mem.base.x, mem.base.y, vmax, 0.55);
  }

  function isBadSite(x, y) {
    var j;
    for (j = 0; j < mem.badSites.length; j++) {
      var b = mem.badSites[j];
      if (t < b.until && dist(x, y, b.x, b.y) < 6.5) return true;
    }
    return false;
  }

  function canTakeSample(sd, sv) {
    if (mem.mode === "sample") return false;
    if (carried >= mem.capacity - 0.01) return false;
    if (!(sv > 0)) return false;
    if (sd > 8.0) return false;
    if (t < mem.siteCooldownUntil) return false;
    var bd = baseDistance();
    if (carried > 0.01 && bd < 6.0) return false;
    var sp = Math.max(0.25, Math.min(0.62, mem.avgSpeed));
    var needT = (bd + sd) / sp + 18.0 + 8.0;
    if (timeLeft < needT + 5.0) return false;
    var eNeed = (bd + sd + 30) * Math.max(0.0004, mem.ePM) * (1 + 0.15 * (carried + 1)) + 0.045;
    if (battery < 0.08) return false;
    if (battery < eNeed && bd > 5) return false;
    return true;
  }

  function startSample(sn, sd) {
    var br = (finite(+sn.bearing) ? +sn.bearing : 0) * D2R;
    var sxSite = mem.px + sd * Math.cos(mem.h + br);
    var sySite = mem.py + sd * Math.sin(mem.h + br);
    var hi = -1;
    if (mem.target && mem.target.type === "hint") hi = mem.target.idx;
    else if (mem.search && mem.search.hintIdx >= 0) hi = mem.search.hintIdx;
    mem.sample = {
      startT: t,
      carriedBefore: carried,
      lastSeen: t,
      siteX: sxSite,
      siteY: sySite,
      hintIdx: hi
    };
    mem.mode = "sample";
    mem.path = null;
  }

  function abortSample() {
    if (mem.sample) {
