      if (mem.badSites.length > 40) mem.badSites.shift();
    }
    mem.sample = null;
    mem.mode = "work";
    mem.siteCooldownUntil = t + 3.0;
  }

  function markSampled(x, y) {
    var idx = mem.sample ? mem.sample.hintIdx : -1;
    if (idx < 0 && mem.target && mem.target.type === "hint") idx = mem.target.idx;
    var j;
    if (idx >= 0 && mem.hints[idx]) mem.hints[idx].status = 1;
    var bestD = 15.0;
    var bestI = -1;
    for (j = 0; j < mem.hints.length; j++) {
      var hh = mem.hints[j];
      if (hh.status !== 0) continue;
      var dd = dist(hh.x, hh.y, x, y);
      if (dd < bestD) { bestD = dd; bestI = j; }
      if (dd < 8.0) hh.status = 1;
    }
    if (bestI >= 0) mem.hints[bestI].status = 1;
  }

  function controlSample() {
    var s = mem.sample;
    if (!s) { mem.mode = "work"; return null; }
    if (carried > s.carriedBefore + 0.1) {
      markSampled(s.siteX, s.siteY);
      mem.sample = null;
      mem.mode = "return";
      mem.target = null;
      mem.search = null;
      mem.path = null;
      mem.siteCooldownUntil = t + 0.7;
      return wheelCtrl(0, 0, true);
    }

    var sn = obs.site;
    var sd = 999;
    var br = 0;
    var seen = false;
    if (sn && finite(+sn.distance)) {
      sd = +sn.distance;
      br = (finite(+sn.bearing) ? +sn.bearing : 0) * D2R;
      seen = true;
      s.lastSeen = t;
      s.siteX = mem.px + sd * Math.cos(mem.h + br);
      s.siteY = mem.py + sd * Math.sin(mem.h + br);
    } else {
      sd = dist(mem.px, mem.py, s.siteX, s.siteY);
      if (!finite(sd)) sd = 999;
    }

    if (battery < 0.065 || timeLeft < 12) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }
    if (!seen && drilling <= 0.001 && t - s.lastSeen > 4.0) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }
    if (t - s.startT > 52 && drilling <= 0.001) {
      abortSample();
      return wheelCtrl(0, 0, true);
    }

    if (sd > 1.35) {
      var relS = wrap(Math.atan2(s.siteY - mem.py, s.siteX - mem.px) - mem.h);
      var vmaxS = sd > 4 ? 0.36 : (sd > 2.2 ? 0.28 : 0.20);
      return driveRelative(relS, sd, vmaxS, 0.72);
    }

    var still = Math.abs(vAvg) < 0.12 && Math.abs(wL) < 0.17 && Math.abs(wR) < 0.17;
    var cm = wheelCtrl(0, 0, true);
    var dr = false;
    if (sd <= 1.48 && (still || drilling > 0.001 || t - s.lastSeen < 0.9)) dr = true;
    return { left: cm.left, right: cm.right, drill: dr };
  }

  function invalidateTarget() {
    if (mem.target) {
      if (mem.target.type === "hint" && mem.hints[mem.target.idx]) {
        mem.hints[mem.target.idx].status = 2;
      } else if (mem.target.type === "explore" && mem.explorePts[mem.target.idx]) {
        mem.explorePts[mem.target.idx].used = true;
      }
    }
    mem.target = null;
    mem.search = null;
    mem.path = null;
    mem.mode = "work";
  }

  var bumpNow = false;
  if (typeof obs.bumped === "number") {
    var bv = +obs.bumped;
    if (bv > mem.lastBumpVal + 0.5) bumpNow = true;
    if (bv > mem.lastBumpVal) mem.lastBumpVal = bv;
  } else {
    if (obs.bumped && !mem.lastBumpBool) bumpNow = true;
    mem.lastBumpBool = !!obs.bumped;
  }
  if (bumpNow) {
    mem.lastBumpT = t;
    mem.escapeUntil = Math.max(mem.escapeUntil, t + 1.5);
    mem.escapeDir = sideOpen();
    if (!mem.escapeDir) mem.escapeDir = Math.sin(t * 2.11) > 0 ? 1 : -1;
    mem.path = null;
    markObs(mem.px + Math.cos(mem.h) * 0.85, mem.py + Math.sin(mem.h) * 0.85);
    if (mem.sample) abortSample();
    if (mem.target) {
      if (mem.bumpTargetIdx === mem.target.idx) mem.bumpTargetCount++;
      else { mem.bumpTargetIdx = mem.target.idx; mem.bumpTargetCount = 1; }
      if (mem.bumpTargetCount >= 3) {
        invalidateTarget();
        mem.bumpTargetIdx = -1;
        mem.bumpTargetCount = 0;
      }
    } else {
      mem.bumpTargetIdx = -1;
      mem.bumpTargetCount = 0;
    }
  }

  if (t - mem.stuckT > 2.5) {
    var moved = dist(mem.px, mem.py, mem.stuckX, mem.stuckY);
    var turnCmd = Math.abs(mem.lastCmdL - mem.lastCmdR);
    var driveCmd = Math.max(Math.abs(mem.lastCmdL), Math.abs(mem.lastCmdR));
    if (moved < 0.12 && driveCmd > 0.24 && turnCmd < 0.62 &&
        mem.gpsSameT < 4.5 && !docked && !mem.sample) {
      mem.escapeUntil = Math.max(mem.escapeUntil, t + 1.45);
      mem.escapeDir = sideOpen();
      if (!mem.escapeDir) mem.escapeDir = Math.sin(t * 1.67) > 0 ? 1 : -1;
      mem.path = null;
      if (mem.target) {
        if (mem.stuckTargetIdx === mem.target.idx) mem.stuckTargetCount++;
        else { mem.stuckTargetIdx = mem.target.idx; mem.stuckTargetCount = 1; }
        if (mem.stuckTargetCount >= 3) {
          invalidateTarget();
          mem.stuckTargetIdx = -1;
          mem.stuckTargetCount = 0;
        }
      }
    }
    mem.stuckT = t;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
  }

  if (carried > mem.prevCarried + 0.1) {
    var sxp = mem.sample ? mem.sample.siteX : mem.px;
    var syp = mem.sample ? mem.sample.siteY : mem.py;
    markSampled(sxp, syp);
    mem.sample = null;
    mem.mode = "return";
    mem.target = null;
    mem.search = null;
    mem.path = null;
    mem.siteCooldownUntil = t + 0.8;
  }
  if (carried < mem.prevCarried - 0.1 || delivered > mem.prevDelivered + 0.1) {
    mem.mode = "work";
    mem.target = null;
    mem.search = null;
    mem.sample = null;
    mem.path = null;
    mem.chargeStart = t;
    mem.stuckTargetIdx = -1;
    mem.stuckTargetCount = 0;
    mem.bumpTargetIdx = -1;
    mem.bumpTargetCount = 0;
  }

  if (t < mem.escapeUntil) {
    var edir = mem.escapeDir || 1;
    var ev = -0.24;
    var eom = edir * 0.72;
    var etl = ev - eom * WB * 0.5;
    var etr = ev + eom * WB * 0.5;
    return finish(wheelCtrl(etl, etr, false));
  }

  if (!mem.sample && carried < mem.capacity - 0.01 && obs.site && t > mem.siteCooldownUntil) {
    var sd0 = finite(+obs.site.distance) ? +obs.site.distance : 99;
    var sv0 = finite(+obs.site.value) ? +obs.site.value : 0;
    if (sd0 <= 7.8 && sv0 > 0) {
      var br0 = (finite(+obs.site.bearing) ? +obs.site.bearing : 0) * D2R;
      var sx0 = mem.px + sd0 * Math.cos(mem.h + br0);
      var sy0 = mem.py + sd0 * Math.sin(mem.h + br0);
      if (!isBadSite(sx0, sy0) && canTakeSample(sd0, sv0)) {
