        var outS0 = controlSample();
        if (outS0) return finish(outS0);
      }
    }
  }

  if (mem.sample) {
    var outS = controlSample();
    if (outS) return finish(outS);
  }

  var bdNow = baseDistance();
  if (carried > 0.01) {
    if (docked || bdNow <= 2.75) return finish(wheelCtrl(0, 0, true));
    return finish(goBase(0.58));
  }

  var atBase = !!(docked || bdNow <= 2.8);
  if (atBase) {
    mem.mode = "work";
    if (battery < 0.55 && timeLeft > 95) {
      if (mem.chargeStart === null || mem.chargeStart === undefined) mem.chargeStart = t;
      if (t - mem.chargeStart < 24 && battery < 0.82 && timeLeft > 55) {
        return finish(wheelCtrl(0, 0, true));
      }
      mem.chargeStart = null;
    } else {
      mem.chargeStart = null;
    }
    if (battery < 0.24 && timeLeft > 45) return finish(wheelCtrl(0, 0, true));
  } else if (battery < 0.12 && timeLeft > 30) {
    mem.mode = "return";
    return finish(goBase(0.50));
  }

  function startSearch(idx) {
    var h = mem.hints[idx];
    if (!h) return;
    var pts = [{ x: h.x, y: h.y }];
    var med = mem.medEst || 1;
    var maxR = 12 + Math.min(12, 6 * Math.max(0.5, h.est / med));
    var r;
    for (r = 6; r <= maxR + 0.01; r += 6) {
      var n = Math.max(6, Math.ceil(2 * Math.PI * r / 10));
      var off = ((Math.floor(r / 6) % 2) * Math.PI / n);
      var j;
      for (j = 0; j < n; j++) {
        var ang = 2 * Math.PI * j / n + off;
        var px = h.x + r * Math.cos(ang);
        var py = h.y + r * Math.sin(ang);
        if (px > mem.minX + 1.0 && px < mem.maxX - 1.0 && py > mem.minY + 1.0 && py < mem.maxY - 1.0) {
          pts.push({ x: px, y: py });
        }
      }
    }
    mem.search = {
      hintIdx: idx,
      pts: pts,
      idx: 0,
      startT: t,
      wpStart: t,
      limit: 42 + (h.est > mem.medEst * 1.5 ? 23 : 0)
    };
    mem.mode = "search";
    mem.path = null;
  }

  function handleSearch() {
    var s = mem.search;
    if (!s) return null;
    var h = mem.hints[s.hintIdx];
    if (!h || h.status !== 0) {
      mem.search = null;
      mem.target = null;
      mem.mode = "work";
      return wheelCtrl(0, 0, true);
    }
    var sci = finite(+obs.science) ? +obs.science : 0;
    if (t - s.startT > s.limit) {
      h.status = 2;
      mem.search = null;
      mem.target = null;
      mem.mode = "work";
      mem.path = null;
      return wheelCtrl(0, 0, true);
    }
    if (t - s.startT > 9 && sci < 0.005 && !obs.site) {
      h.status = 2;
      mem.search = null;
      mem.target = null;
      mem.mode = "work";
      mem.path = null;
      return wheelCtrl(0, 0, true);
    }
    if (!s.pts || s.idx >= s.pts.length) {
      h.status = 2;
      mem.search = null;
      mem.target = null;
      mem.mode = "work";
      mem.path = null;
      return wheelCtrl(0, 0, true);
    }
    var wp = s.pts[s.idx];
    var dwp = dist(mem.px, mem.py, wp.x, wp.y);
    if (dwp < 0.90 || t - s.wpStart > 15.0) {
      s.idx++;
      s.wpStart = t;
      if (s.idx >= s.pts.length) {
        h.status = 2;
        mem.search = null;
        mem.target = null;
        mem.mode = "work";
        mem.path = null;
        return wheelCtrl(0, 0, true);
      }
      wp = s.pts[s.idx];
    }
    return navigate(wp.x, wp.y, 0.54, 0.52);
  }

  function chooseTarget() {
    var best = -1;
    var bestScore = -1e18;
    var med = mem.medEst || 1;
    var sp = Math.max(0.25, Math.min(0.62, mem.avgSpeed * 0.92));
    var j;
    for (j = 0; j < mem.hints.length; j++) {
      var h = mem.hints[j];
      if (h.status !== 0) continue;
      var d = dist(mem.px, mem.py, h.x, h.y);
      var db = dist(h.x, h.y, mem.base.x, mem.base.y);
      var extraSearch = h.est > med * 1.4 ? 25 : 16;
      var needT = (d + db) / sp + extraSearch + 22;
      if (timeLeft < needT + 9) continue;
      var eNeed = (d + db + 35) * Math.max(0.0004, mem.ePM) * (1 + 0.15 * carried) + 0.06;
      if (battery < eNeed && d > 8) continue;
      var score = h.est / Math.pow(15 + d + 0.82 * db, 1.18);
      score *= 1 + 9 / (d + 10);
      if (score > bestScore) {
        bestScore = score;
        best = j;
      }
    }
    if (best >= 0) {
      mem.target = { type: "hint", idx: best };
      mem.mode = "goto";
      mem.search = null;
      mem.path = null;
      mem.stuckTargetIdx = -1;
      mem.stuckTargetCount = 0;
      mem.bumpTargetIdx = -1;
      mem.bumpTargetCount = 0;
      return true;
    }

    var ex = -1;
    var bestD = 1e18;
    for (j = 0; j < mem.explorePts.length; j++) {
      var p = mem.explorePts[j];
      if (p.used) continue;
      var d2 = dist(mem.px, mem.py, p.x, p.y);
      if (d2 < 4.0) { p.used = true; continue; }
      var db2 = dist(p.x, p.y, mem.base.x, mem.base.y);
      var needT2 = (d2 + db2) / sp + 20;
      if (timeLeft < needT2 + 8) continue;
      if (d2 < bestD) {
        bestD = d2;
        ex = j;
      }
    }
    if (ex >= 0) {
      var pp = mem.explorePts[ex];
      mem.target = { type: "explore", idx: ex, x: pp.x, y: pp.y };
      mem.mode = "goto";
      mem.search = null;
      mem.path = null;
      return true;
    }
    return false;
  }

  if (mem.target) {
    var valid = true;
    if (mem.target.type === "hint") {
      var ht = mem.hints[mem.target.idx];
      if (!ht || ht.status !== 0) valid = false;
    } else if (mem.target.type === "explore") {
      var et = mem.explorePts[mem.target.idx];
      if (!et || et.used) valid = false;
    } else {
