  }

  function startSample(sn, sd) {
    if (!sn) return;
    var br = (finiteNum(+sn.bearing) ? +sn.bearing : 0) * D2R;
    var sxSite = mem.px + sd * Math.cos(mem.h + br);
    var sySite = mem.py + sd * Math.sin(mem.h + br);
    var hi = -1;
    if (mem.search && mem.search.hintIdx >= 0) hi = mem.search.hintIdx;
    else if (mem.target && mem.target.type === "hint") hi = mem.target.idx;
    mem.sample = {
      t0: t,
      carried0: carried,
      siteX: sxSite,
      siteY: sySite,
      lastSeen: t,
      hintIdx: hi
    };
    mem.mode = "sample";
  }

  function markSampled(s) {
    var x = s && finiteNum(s.siteX) ? s.siteX : mem.px;
    var y = s && finiteNum(s.siteY) ? s.siteY : mem.py;
