      mem.search = null;
      mem.target = null;
      mem.mode = "idle";
      return wheelCtrl(0, 0, true);
    }

    var maxT = h.est > (mem.medEst || 1) * 2 ? 80 : 60;
    if (t - s.t0 > maxT) {
