    if (mem.target.type === "hint") {
      var th = mem.hints[mem.target.idx];
      if (!th || th.status !== 0) ok = false;
    } else if (mem.target.type === "explore") {
      var ep = mem.explore[mem.target.idx];
      if (!ep || ep.used) ok = false;
    } else {
      ok = false;
    }
    if (!ok) {
      mem.target = null;
      mem.search = null;
      mem.mode = "idle";
    }
  }

  if (!mem.target && !mem.returning) {
    var nt = pickTarget();
    if (nt) {
      mem.target = nt;
      mem.mode = nt.type === "hint" ? "goto" : "explore";
      mem.search = null;
      mem.bumpTarget = -1;
      mem.bumpCount = 0;
    } else {
      if (carried > 0.01) {
        mem.returning = true;
        return finish(goBase(0.85));
      }
      return finish(wheelCtrl(0, 0, true));
    }
  }

  if (mem.target) {
    if (mem.target.type === "hint") {
      var h = mem.hints[mem.target.idx];
      if (!h || h.status !== 0) {
        mem.target = null;
        mem.search = null;
        mem.mode = "idle";
      } else {
        var dh = dist(mem.px, mem.py, h.x, h.y);
        if (dh < 7.5 && !mem.search) {
          var sciNow = finiteNum(+obs.science) ? +obs.science : 0;
          if (sciNow <= 1e-12 && !site) {
            h.status = 2;
            mem.target = null;
            mem.search = null;
            mem.mode = "idle";
            return finish(wheelCtrl(0, 0, true));
