        if (mem.search && mem.search.hintIdx === mem.target.idx) {
          var sc = controlSearch();
          if (sc) return finish(sc);
        } else {
          if (dh < 8.5) {
            startSearch(mem.target.idx);
            var sc2 = controlSearch();
            if (sc2) return finish(sc2);
          }
          return finish(driveToWorld(h.x, h.y, 0.85, 1.0));
        }
      }
    } else if (mem.target.type === "explore") {
      var pp2 = mem.explore[mem.target.idx];
      if (!pp2 || pp2.used) {
        mem.target = null;
        mem.mode = "idle";
      } else {
        var de = dist(mem.px, mem.py, pp2.x, pp2.y);
        if (de < 2.5) {
          pp2.used = true;
          mem.target = null;
          mem.mode = "idle";
          return finish(wheelCtrl(0, 0, true));
        }
        return finish(driveToWorld(pp2.x, pp2.y, 0.75, 0.8));
      }
    }
  }

  return finish(wheelCtrl(0, 0, true));
}

